import { teleportStyle } from '@util/script';
import { createApp, type App as VueApplication } from 'vue';
import { createPinia } from 'pinia';
import TangquanApp from './App.vue';
import type { TangquanGameUiController, TangquanGameUiServices } from './types';

function syncOverlayViewport(iframe: HTMLIFrameElement): () => void {
  const parentWindow = window.parent;
  const visualViewport = parentWindow.visualViewport;

  const applyViewport = () => {
    const width = visualViewport?.width ?? parentWindow.innerWidth;
    const height = visualViewport?.height ?? parentWindow.innerHeight;
    iframe.style.left = `${visualViewport?.offsetLeft ?? 0}px`;
    iframe.style.top = `${visualViewport?.offsetTop ?? 0}px`;
    iframe.style.width = `${width}px`;
    iframe.style.height = `${height}px`;
  };

  applyViewport();
  parentWindow.addEventListener('resize', applyViewport);
  visualViewport?.addEventListener('resize', applyViewport);
  visualViewport?.addEventListener('scroll', applyViewport);

  return () => {
    parentWindow.removeEventListener('resize', applyViewport);
    visualViewport?.removeEventListener('resize', applyViewport);
    visualViewport?.removeEventListener('scroll', applyViewport);
  };
}

export function createTangquanGameUi(services: TangquanGameUiServices): TangquanGameUiController {
  const parentDocument = window.parent.document;
  let app: VueApplication<Element> | null = null;
  let iframeElement: HTMLIFrameElement | null = null;
  let destroyStyle: (() => void) | null = null;
  let destroyViewport: (() => void) | null = null;
  let loading = false;

  function mount() {
    if (iframeElement || loading) {
      return;
    }

    loading = true;
    services.log.info('正式前端', '开始挂载 Vue 界面');
    const iframe = parentDocument.createElement('iframe');
    iframe.setAttribute('script_id', getScriptId());
    iframe.setAttribute('frameborder', '0');
    iframe.setAttribute('title', '未开之花');
    iframe.style.cssText =
      'position:fixed;left:0;top:0;width:100%;height:100%;z-index:999980;border:0;background:#100b08;';
    iframe.srcdoc = '<!doctype html><html><head></head><body></body></html>';

    iframe.addEventListener('load', () => {
      const iframeDocument = iframe.contentDocument;
      if (!iframeDocument) {
        services.log.error('正式前端', 'Vue 界面挂载失败：无法访问 iframe 文档');
        loading = false;
        return;
      }

      iframeDocument.documentElement.style.cssText = 'width:100%;height:100%;margin:0;overflow:hidden;';
      iframeDocument.body.style.cssText = 'width:100%;height:100%;margin:0;overflow:hidden;';
      destroyStyle = teleportStyle(iframeDocument.head).destroy;
      app = createApp(TangquanApp, {
        services,
        onClose: close,
      }).use(createPinia());
      app.mount(iframeDocument.body);
      loading = false;
      services.log.info('正式前端', 'Vue 界面挂载完成');
    });

    parentDocument.body.appendChild(iframe);
    iframeElement = iframe;
    destroyViewport = syncOverlayViewport(iframe);
  }

  function open() {
    if (!iframeElement) {
      mount();
      return;
    }
    iframeElement.style.display = 'block';
    services.log.info('正式前端', '打开 Vue 界面');
  }

  function close() {
    if (!iframeElement) {
      return;
    }
    iframeElement.style.display = 'none';
    services.log.info('正式前端', '关闭 Vue 界面');
  }

  function isVisible() {
    return iframeElement !== null && iframeElement.style.display !== 'none';
  }

  function toggle() {
    if (isVisible()) {
      close();
    } else {
      open();
    }
  }

  function dispose() {
    services.log.info('正式前端', '卸载 Vue 界面');
    app?.unmount();
    app = null;
    destroyStyle?.();
    destroyStyle = null;
    destroyViewport?.();
    destroyViewport = null;
    iframeElement?.remove();
    iframeElement = null;
    loading = false;
  }

  return {
    open,
    close,
    toggle,
    isVisible,
    dispose,
  };
}
