/**
 * 汤泉零层美化
 *
 * 通用0层视觉锁定脚本：
 * - 保留真实聊天楼层作为上下文
 * - 视觉上隐藏0层以外的楼层
 * - 将最新楼层镜像到0层显示，并让显示正则照常生效
 */
import { TANGQUAN_ASSET_SLOTS } from './assets/assetSlots';
import { createLatestFloorBeautifier } from './beautify/latestFloorBeautifier';
import { createZeroLockController } from './core/zeroLock';
import { createTangquanLogger } from './debug/logger';
import { createTangquanModeRuntimeService } from './runtime/modeRuntime';
import { createTangquanMvuRuntimeService } from './runtime/mvuRuntime';
import { createFullSaveController } from './save/saveController';
import { createUserProfileWorldbookService } from './save/userProfileWorldbook';
import { createWorldbookSaveService } from './save/worldbookSave';
import { useZeroStore } from './stores/zeroStore';
import { createTangquanGameUi } from './ui/app/gameUi';
import { createTangquanLoadingOverlay } from './ui/loadingOverlay';
import { createTangquanWorldbookRuntimeService } from './worldbook/worldbookRuntime';
$(() => {
    const pinia = createPinia();
    const log = createTangquanLogger();
    log.info('启动', '脚本开始加载');
    const store = useZeroStore(pinia);
    const controller = createZeroLockController(store);
    const loading = createTangquanLoadingOverlay(log);
    const beautifier = createLatestFloorBeautifier();
    const worldbookSave = createWorldbookSaveService({ loading, log });
    const userProfileWorldbook = createUserProfileWorldbookService({
        resolveWorldbookName: worldbookSave.resolveWorldbookName,
        log,
    });
    const worldbookRuntime = createTangquanWorldbookRuntimeService({
        resolveWorldbookName: worldbookSave.resolveWorldbookName,
        log,
    });
    const mvuRuntime = createTangquanMvuRuntimeService({ log });
    const runtime = createTangquanModeRuntimeService({
        loading,
        log,
        mvu: mvuRuntime,
        worldbook: worldbookRuntime,
    });
    const save = createFullSaveController({
        worldbookSave,
        loading,
        log,
        beautifier,
        userProfileWorldbook,
    });
    const gameUi = createTangquanGameUi({
        save,
        loading,
        log,
        assetSlots: TANGQUAN_ASSET_SLOTS,
        runtime,
        mvuRuntime,
        worldbookRuntime,
        zeroLock: controller,
        beautifier,
    });
    appendInexistentScriptButtons([{ name: '打开未开之花', visible: true }]);
    const openUiButton = eventOn(getButtonEvent('打开未开之花'), () => {
        log.info('按钮', '打开未开之花');
        gameUi.open();
    });
    const frontend = {
        loading,
        save,
        worldbookSave,
        userProfileWorldbook,
        worldbookRuntime,
        mvuRuntime,
        runtime,
        beautifier,
        gameUi,
        assetSlots: TANGQUAN_ASSET_SLOTS,
        log,
        dispose: () => {
            log.info('卸载', '正在卸载前端控制器');
            openUiButton.stop();
            gameUi.dispose();
            beautifier.dispose();
            loading.dispose();
            log.dispose();
        },
    };
    const parentWindow = window.parent;
    let disposed = false;
    function disposeAll() {
        if (disposed) {
            return;
        }
        disposed = true;
        frontend.dispose();
        controller.dispose();
    }
    parentWindow.tangquanZeroLayer = controller;
    parentWindow.tangquanFrontend = frontend;
    parentWindow.tangquanZeroLayerEmergencyDisable = () => {
        log.warn('应急卸载', '用户触发应急卸载');
        disposeAll();
        console.info('[汤泉零层美化] 已应急卸载');
    };
    gameUi.open();
    $(window).on('pagehide', () => {
        disposeAll();
        delete parentWindow.tangquanFrontend;
        delete parentWindow.tangquanZeroLayer;
        delete parentWindow.tangquanZeroLayerEmergencyDisable;
    });
    log.info('启动', '脚本已加载');
});
