mB,CACnB,iBACF,CACF","sourcesContent":["<template>\n  <main\n    v-if=\"activePage !== 'play'\"\n    id=\"titleScreen\"\n    class=\"title-screen\"\n    :class=\"{ 'panel-open': activePanel !== 'landing' }\"\n    :data-font-size=\"settings.fontSize\"\n    :data-font-family=\"settings.fontFamily\"\n    :data-layout=\"settings.layout\"\n    :data-panel=\"settings.panel\"\n    aria-label=\"未开之花标题画面\"\n  >\n    <img class=\"title-bg\" :src=\"titleBgUrl\" alt=\"\" />\n    <div class=\"vignette\" />\n    <div class=\"mist\" />\n    <svg class=\"rain-lines\" viewBox=\"0 0 1366 768\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n      <defs>\n        <linearGradient id=\"rainFade\" x1=\"0\" x2=\"0\" y1=\"0\" y2=\"1\">\n          <stop offset=\"0\" stop-color=\"#fff2de\" stop-opacity=\"0\" />\n          <stop offset=\"0.48\" stop-color=\"#fff2de\" stop-opacity=\"0.5\" />\n          <stop offset=\"1\" stop-color=\"#fff2de\" stop-opacity=\"0\" />\n        </linearGradient>\n      </defs>\n      <path d=\"M338 0v760M402 0v760M718 0v760M846 0v760M1016 0v760\" stroke=\"url(#rainFade)\" stroke-width=\"1\" />\n    </svg>\n\n    <div class=\"top-name\">Mihiraki no Hana</div>\n\n    <section class=\"title-copy\">\n      <small>现代汤泉经营与邂逅</small>\n      <h1>未开之花</h1>\n      <p class=\"subtitle\">夜雾贴着木廊，灯火从汤池边慢慢亮起。选定身份，然后把今晚交给水声。</p>\n    </section>\n\n    <nav class=\"main-menu\" aria-label=\"标题菜单\">\n      <button\n        v-for=\"item in titleMenuItems\"\n        :key=\"item.key\"\n        class=\"menu-button\"\n        :class=\"{ 'is-active': item.key === activePanel || (item.key === 'start' && activePanel === 'modes') }\"\n        type=\"button\"\n        :disabled=\"busy\"\n        @click=\"handleTitleMenu(item.key)\"\n      >\n        {{ item.label }}\n      </button>\n    </nav>\n\n    <button class=\"continue-pill\" type=\"button\" :disabled=\"busy\" @click=\"openModesPanel\">开始游戏</button>\n\n    <section class=\"mode-dock\" :class=\"{ 'is-open': activePanel === 'modes' }\" aria-label=\"游玩身份选择\">\n      <header class=\"mode-title\">\n        <div>\n          <h2>选择游玩身份</h2>\n          <p>每份存档创建后，游玩身份无法修改。</p>\n        </div>\n        <button class=\"enter-button\" type=\"button\" :disabled=\"busy\" @click=\"openLoadPanel\">选择存档</button>\n      </header>\n      <div class=\"mode-row\">\n        <button\n          v-for=\"mode in modes\"\n          :key=\"mode.key\"\n          class=\"mode-ribbon\"\n          :class=\"{ 'is-selected': selectedMode === mode.key }\"\n          type=\"button\"\n          :disabled=\"busy\"\n          @click=\"selectedMode = mode.key\"\n        >\n          <span class=\"mode-mark\">\n            <svg viewBox=\"0 0 64 64\" aria-hidden=\"true\">\n              <path d=\"M32 4 56 18v28L32 60 8 46V18Z\" fill=\"rgba(11,8,6,.38)\" stroke=\"rgba(212,176,110,.68)\" />\n              <path d=\"M20 18h24M20 46h24M14 32h36\" stroke=\"rgba(247,236,220,.22)\" />\n            </svg>\n            {{ mode.mark }}\n          </span>\n          <h3>{{ mode.title }}</h3>\n          <p>{{ mode.note }}</p>\n        </button>\n      </div>\n    </section>\n\n    <section class=\"floating-list save-list\" :class=\"{ 'is-open': activePanel === 'load' }\" aria-label=\"存档\">\n      <header class=\"floating-title\">\n        <div>\n          <h2>存档</h2>\n          <p>选择一份存档，开始新的故事，或回到未完的夜晚。</p>\n        </div>\n        <button class=\"enter-button\" type=\"button\" :disabled=\"busy\" @click=\"loadSlots\">刷新列表</button>\n      </header>\n\n      <div class=\"save-slot-grid\">\n        <button\n          v-for=\"slot in slotViews\"\n          :key=\"slot.id\"\n          class=\"save-slot-ribbon\"\n          :class=\"{ 'is-selected': selectedSlotId === slot.id, 'is-active': runtime.activeSlotId === slot.id, 'is-empty': !slot.meta }\"\n          type=\"button\"\n          :disabled=\"busy\"\n          @click=\"selectedSlotId = slot.id\"\n        >\n          <span>{{ slot.label }}</span>\n          <strong>{{ slot.meta?.label || '空白存档' }}</strong>\n          <small v-if=\"slot.meta\">{{ slot.meta.mode }} · {{ formatDate(slot.meta.updatedAt) }}</small>\n          <small v-else>可以从这里开始</small>\n          <em v-if=\"slot.meta\">已保存 · {{ formatMB(slot.meta.byteLength) }}</em>\n          <em v-else>尚未开始</em>\n        </button>\n      </div>\n\n      <div class=\"slot-actions\">\n        <button class=\"setting-choice is-primary\" type=\"button\" :disabled=\"busy\" @click=\"startGame\">\n          {{ selectedSlotMeta ? '覆盖新建' : '新建' }}\n        </button>\n        <button class=\"setting-choice\" type=\"button\" :disabled=\"busy || !selectedSlotMeta\" @click=\"loadSelectedSlot\">载入</button>\n        <button\n          v-if=\"savePanelContext === 'play'\"\n          class=\"setting-choice\"\n          type=\"button\"\n          :disabled=\"busy || runtime.activeMode === '未选择'\"\n          @click=\"saveSelectedSlot\"\n        >\n          保存\n        </button>\n        <button v-if=\"savePanelContext === 'play'\" class=\"setting-choice\" type=\"button\" :disabled=\"busy\" @click=\"returnToPlay\">\n          返回游戏\n        </button>\n        <button class=\"setting-choice\" type=\"button\" :disabled=\"busy || !selectedSlotMeta\" @click=\"deleteSelectedSlot\">删除</button>\n        <button class=\"setting-choice\" type=\"button\" :disabled=\"busy\" @click=\"showSaveTools = !showSaveTools\">\n          存档管理\n        </button>\n      </div>\n\n      <div v-if=\"showSaveTools\" class=\"slot-actions save-tools\">\n        <button class=\"setting-choice\" type=\"button\" :disabled=\"busy || !selectedSlotMeta\" @click=\"inspectSelectedSlot\">检查存档</button>\n        <button class=\"setting-choice\" type=\"button\" :disabled=\"busy || !selectedSlotMeta\" @click=\"repairSelectedSlot\">修复存档</button>\n        <button class=\"setting-choice\" type=\"button\" :disabled=\"busy || !selectedSlotMeta\" @click=\"exportSelectedSlot\">导出存档</button>\n        <button class=\"setting-choice\" type=\"button\" :disabled=\"busy\" @click=\"chooseImportFile\">导入存档</button>\n      </div>\n\n      <input ref=\"importInput\" class=\"visually-hidden\" type=\"file\" accept=\"application/json,.json\" @change=\"handleImportFile\" />\n\n      <div v-if=\"inspection\" class=\"inspection-strip\" :data-ok=\"inspection.ok ? 'true' : 'false'\">\n        <header>\n          <strong>{{ inspection.ok ? '检查通过' : '发现异常' }}</strong>\n          <span>{{ inspection.messageCount }} 楼 · {{ inspection.chunkCount }}片 · {{ formatMB(inspection.byteLength) }}</span>\n        </header>\n        <article v-for=\"(issue, index) in inspection.issues\" :key=\"index\" :data-level=\"issue.level\">\n          <b>{{ issue.level }}</b>\n          <p>{{ issue.message }}</p>\n          <pre v-if=\"issue.detail !== undefined\">{{ formatDetail(issue.detail) }}</pre>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"floating-list profile-list\" :class=\"{ 'is-open': activePanel === 'profile' }\" aria-label=\"用户信息\">\n      <header class=\"floating-title\">\n        <div>\n          <h2>创建人设</h2>\n          <p>这些内容会成为你在未开之花中的基本印象。</p>\n        </div>\n        <button class=\"enter-button\" type=\"button\" :disabled=\"busy\" @click=\"activePanel = 'load'\">返回</button>\n      </header>\n\n      <div class=\"profile-form\">\n        <label class=\"profile-field\">\n          <span>姓名</span>\n          <input v-model=\"profileName\" class=\"profile-input\" type=\"text\" maxlength=\"40\" placeholder=\"输入你的名字\" />\n        </label>\n\n        <div class=\"profile-field\">\n          <span>性别</span>\n          <div class=\"settings-options\">\n            <button\n              v-for=\"option in profileGenderOptions\"\n              :key=\"option.key\"\n              class=\"setting-choice\"\n              :class=\"{ 'is-selected': profileGenderKey === option.key }\"\n              type=\"button\"\n              :disabled=\"busy\"\n              @click=\"profileGenderKey = option.key\"\n            >\n              {{ option.label }}\n            </button>\n          </div>\n        </div>\n\n        <label v-if=\"profileGenderKey === '自定义'\" class=\"profile-field\">\n          <span>自定义</span>\n          <input v-model=\"profileGenderText\" class=\"profile-input\" type=\"text\" maxlength=\"40\" placeholder=\"输入性别称呼\" />\n        </label>\n\n        <label class=\"profile-field\">\n          <span>人物设定</span>\n          <textarea\n            v-model=\"profileDescription\"\n            class=\"profile-textarea\"\n            maxlength=\"4000\"\n            placeholder=\"写下外貌、性格、经历、偏好或其他你希望被记住的信息。\"\n          />\n        </label>\n      </div>\n\n      <div class=\"slot-actions\">\n        <button class=\"setting-choice\" type=\"button\" :disabled=\"busy\" @click=\"activePanel = 'load'\">返回存档</button>\n        <button class=\"setting-choice is-primary\" type=\"button\" :disabled=\"busy\" @click=\"startGame\">开始</button>\n      </div>\n    </section>\n\n    <section class=\"floating-list is-settings\" :class=\"{ 'is-open': activePanel === 'settings' }\" aria-label=\"设置\">\n      <div class=\"settings-panel\">\n        <div v-for=\"group in settingGroups\" :key=\"group.key\" class=\"settings-row\">\n          <div class=\"settings-label\">\n            <strong>{{ group.title }}</strong>\n            <span>{{ group.note }}</span>\n          </div>\n          <div class=\"settings-options\">\n            <button\n              v-for=\"option in group.options\"\n              :key=\"option.value\"\n              class=\"setting-choice\"\n              :class=\"{ 'is-selected': settings[group.key] === option.value }\"\n              type=\"button\"\n              @click=\"updateSetting(group.key, option.value)\"\n            >\n              {{ option.label }}\n            </button>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"floating-list log-list\" :class=\"{ 'is-open': activePanel === 'logs' }\" aria-label=\"运行日志\">\n      <header class=\"floating-title\">\n        <div>\n          <h2>运行日志</h2>\n          <p>{{ logEntries.length }} 条日志，最近错误：{{ recentErrorText }}</p>\n        </div>\n        <div class=\"slot-actions compact\">\n          <button class=\"setting-choice\" type=\"button\" @click=\"refreshLogs\">刷新</button>\n          <button class=\"setting-choice\" type=\"button\" @click=\"copyLogs\">复制</button>\n          <button class=\"setting-choice\" type=\"button\" @click=\"clearLogs\">清空</button>\n        </div>\n      </header>\n      <article v-for=\"entry in logEntries\" :key=\"entry.id\" class=\"floating-item log-entry\" :data-level=\"entry.level\">\n        <h3>{{ entry.scope }} · {{ entry.message }}</h3>\n        <p>{{ entry.at }} · {{ entry.level }}</p>\n        <pre v-if=\"entry.detail !== undefined\">{{ formatDetail(entry.detail) }}</pre>\n      </article>\n    </section>\n\n    <div class=\"toast\" :class=\"{ 'is-show': toastText }\">{{ toastText }}</div>\n  </main>\n\n  <main\n    v-else\n    class=\"play-screen\"\n    :class=\"{ 'mode-menu': isBossMenuVisible, 'mode-scene': !isBossMenuVisible }\"\n    :data-play-mode=\"activeMode\"\n    aria-label=\"未开之花游玩画面\"\n  >\n    <img class=\"scene-bg\" :src=\"currentSceneBg\" alt=\"\" />\n    <div class=\"shade\" />\n    <div class=\"steam\" />\n    <svg class=\"hud-lines\" viewBox=\"0 0 1366 768\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n      <path d=\"M36 42h170M36 714h300M1020 90h260M1180 692h126\" stroke=\"rgba(247,236,220,.24)\" />\n      <path d=\"M180 90v580M1194 138v500\" stroke=\"rgba(247,236,220,.12)\" stroke-dasharray=\"4 8\" />\n    </svg>\n\n    <header class=\"corner-brand\">\n      <span class=\"brand-seal\">汤</span>\n      <span class=\"brand-text\"><strong>未开之花</strong><span>{{ activeMode }}视角</span></span>\n    </header>\n\n    <aside class=\"left-rail\" aria-label=\"当前状态\">\n      <div class=\"identity-plaque\">\n        <b>{{ playPlaque.main }}</b>\n        <span>{{ playPlaque.sub }}</span>\n      </div>\n      <div v-for=\"item in playStatusItems\" :key=\"item.label\" class=\"status-slip\">\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path :d=\"item.icon\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" /></svg>\n        <strong>{{ item.text }}</strong>\n      </div>\n    </aside>\n\n    <div class=\"top-center\">\n      <span class=\"gem\" />\n      <span>{{ currentSlotLabel }}</span>\n      <span class=\"gem\" />\n    </div>\n\n    <div class=\"top-icons\">\n      <button class=\"icon-button\" type=\"button\" title=\"存档\" @click=\"openLoadPanel('play')\">\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\">\n          <path d=\"M5 4h14v16H5zM8 8h8M8 12h8M8 16h5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" />\n        </svg>\n      </button>\n      <button class=\"icon-button\" type=\"button\" title=\"返回标题\" @click=\"returnToTitle\">\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\">\n          <path d=\"M4 12 12 5l8 7v7H4z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" />\n        </svg>\n      </button>\n    </div>\n\n    <div class=\"sprite-spot\" aria-hidden=\"true\">\n      <img :src=\"staffSpriteUrl\" alt=\"\" />\n    </div>\n\n    <nav v-if=\"activeMode === '老板'\" class=\"right-actions\" aria-label=\"快捷操作\">\n      <button class=\"action-pill\" type=\"button\" @click=\"openBossMenu('overview')\">\n        <span>总览</span>\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 13h6V5H4zm10 6h6V5h-6zM4 19h6v-4H4z\" fill=\"currentColor\" /></svg>\n      </button>\n      <button class=\"action-pill\" type=\"button\" @click=\"openBossMenu('schedule')\">\n        <span>排班</span>\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 4h14v16H5zM8 2v4M16 2v4M5 9h14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" /></svg>\n      </button>\n      <button class=\"action-pill\" type=\"button\" @click=\"openBossMenu('employees')\">\n        <span>员工</span>\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 12a4 4 0 1 0-4-4 4 4 0 0 0 4 4Zm7 8a7 7 0 0 0-14 0\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" /></svg>\n      </button>\n      <button class=\"action-pill\" type=\"button\" @click=\"openBossMenu('recruit')\">\n        <span>招聘</span>\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 5v14M5 12h14\" stroke=\"currentColor\" stroke-width=\"1.8\" /></svg>\n      </button>\n      <button class=\"action-pill\" type=\"button\" @click=\"openBossMenu('settlement')\">\n        <span>结算</span>\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M7 4h10v16H7zM9 8h6M9 12h6M9 16h3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" /></svg>\n      </button>\n    </nav>\n\n    <nav v-else class=\"right-actions\" aria-label=\"快捷操作\">\n      <button class=\"action-pill\" type=\"button\" @click=\"returnToTitle\">\n        <span>菜单</span>\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 7h16M4 12h16M4 17h16\" stroke=\"currentColor\" stroke-width=\"1.8\" /></svg>\n      </button>\n      <button class=\"action-pill\" type=\"button\" @click=\"openLoadPanel('play')\">\n        <span>存档</span>\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 4h14v16H5zM8 8h8M8 12h8M8 16h5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" /></svg>\n      </button>\n      <button class=\"action-pill\" type=\"button\" @click=\"openSettingsPanel\">\n        <span>设置</span>\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM4 12h2m12 0h2M12 4v2m0 12v2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" /></svg>\n      </button>\n    </nav>\n\n    <section v-if=\"activeMode === '老板'\" class=\"menu-layer\" aria-label=\"老板菜单\">\n      <nav class=\"menu-tabs\" aria-label=\"老板菜单分类\">\n        <button\n          v-for=\"tab in bossTabs\"\n          :key=\"tab.key\"\n          class=\"menu-tab\"\n          :class=\"{ 'is-active': bossView === tab.key }\"\n          type=\"button\"\n          @click=\"openBossMenu(tab.key)\"\n        >\n          {{ tab.title }}\n        </button>\n      </nav>\n\n      <article class=\"menu-main\">\n        <header class=\"menu-head\">\n          <div>\n            <h2>{{ activeBossTab.title }}</h2>\n            <p>{{ activeBossTab.note }}</p>\n          </div>\n          <button class=\"close-button\" type=\"button\" @click=\"closeBossMenu\">返回</button>\n        </header>\n\n        <div class=\"menu-content\">\n          <template v-if=\"bossView === 'overview'\">\n            <div class=\"data-grid three\">\n              <section class=\"metric-line\">\n                <span>今日客流</span>\n                <strong>{{ bossState.客流 }}</strong>\n                <p>接待上限 {{ bossCapacity }}，由评分、排班和维护共同影响。</p>\n              </section>\n              <section class=\"metric-line\">\n                <span>店铺评分</span>\n                <strong>{{ bossState.店铺评分 }}</strong>\n                <p>好评率 {{ percent(bossState.好评率) }}，会影响明日入客。</p>\n              </section>\n              <section class=\"metric-line\">\n                <span>维护度</span>\n                <strong>{{ bossState.基建.维护度 }}</strong>\n                <p>维护偏低会压低客流、评分和员工状态。</p>\n              </section>\n            </div>\n\n            <div class=\"data-grid two spaced\">\n              <section v-if=\"bossHotProject\" class=\"data-line\">\n                <div class=\"line-head\">\n                  <h3>{{ bossHotProject.名称 }}</h3>\n                  <span class=\"tag good\">{{ bossHotProject.热度 }}</span>\n                </div>\n                <p>评分 {{ bossHotProject.评分 }} · 推荐值 {{ percent(bossHotProject.推荐值 / 100) }}</p>\n                <div class=\"thin-meter\" :style=\"{ '--value': `${bossHotProject.推荐值}%` }\"><span /></div>\n              </section>\n              <section class=\"metric-line\">\n                <span>今日毛利</span>\n                <strong>{{ yuan(bossState.结算.毛利) }}</strong>\n                <p>收入 {{ yuan(bossState.结算.收入) }}，支出 {{ yuan(bossState.结算.支出) }}，日薪合计 {{ yuan(bossPayroll) }}。</p>\n              </section>\n            </div>\n\n            <div class=\"data-grid two spaced\">\n              <section class=\"metric-line\">\n                <span>当前位置</span>\n                <strong>{{ bossState.地点 }}</strong>\n                <p>同区域员工：{{ bossCurrentStaffText }}。</p>\n              </section>\n              <section class=\"metric-line\">\n                <span>员工满意</span>\n                <strong>{{ bossAverageSatisfaction }}</strong>\n                <p>低满意会提高离职风险，日薪和休息室会缓解压力。</p>\n              </section>\n            </div>\n\n            <div class=\"data-grid two spaced\">\n              <section class=\"metric-line\">\n                <span>指名占用</span>\n                <strong>{{ bossState.指名.length }}</strong>\n                <p>跨天指名会继续占用对应员工。</p>\n              </section>\n              <section class=\"metric-line\">\n                <span>招聘刷新</span>\n                <strong>{{ bossState.招聘.刷新倒计时 }}</strong>\n                <p>当前候选：{{ bossState.招聘.姓名 }}，拒绝记录 {{ bossState.招聘.拒绝记录 }}。</p>\n              </section>\n            </div>\n\n            <div class=\"data-grid spaced\">\n              <section v-for=\"log in bossState.经营提醒\" :key=\"log\" class=\"data-line\">\n                <h3>{{ log }}</h3>\n                <p>经营提醒会集中显示在这里。</p>\n              </section>\n            </div>\n          </template>\n\n          <template v-else-if=\"bossView === 'schedule'\">\n            <div class=\"schedule\">\n              <div class=\"shift-row\">\n                <div class=\"shift-name\">员工</div>\n                <div v-for=\"part in bossState.时间段\" :key=\"part\" class=\"shift-name\">{{ part }}</div>\n              </div>\n              <div v-for=\"employee in bossState.员工\" :key=\"employee.姓名\" class=\"shift-row\">\n                <div class=\"shift-name\">{{ employee.姓名 }}</div>\n                <button\n                  v-for=\"(slot, index) in employee.排班\"\n                  :key=\"`${employee.姓名}-${index}`\"\n                  class=\"shift-cell\"\n                  :class=\"{ 'is-work': slot !== '休息', 'is-selected': isBossShiftSelected(employee.姓名, index) }\"\n                  type=\"button\"\n                  @click=\"selectBossShift(employee.姓名, index)\"\n                >\n                  <strong>{{ slot }}</strong>\n                  <span>{{ bossState.时间段[index] }}</span>\n                </button>\n              </div>\n            </div>\n\n            <section v-if=\"bossActiveShift\" class=\"schedule-panel\">\n              <h3>{{ bossActiveShift.name }} · {{ bossState.时间段[bossActiveShift.index] }}</h3>\n              <p class=\"hint\">选择这个时间段的位置或状态。</p>\n              <div class=\"option-grid\">\n                <button\n                  v-for=\"choice in bossScheduleChoices\"\n                  :key=\"choice\"\n                  class=\"option-button\"\n                  :class=\"{ 'is-active': currentBossShiftValue === choice }\"\n                  type=\"button\"\n                  @click=\"setBossShiftOption(choice)\"\n                >\n                  {{ choice }}\n                </button>\n              </div>\n            </section>\n            <section v-else class=\"schedule-panel\">\n              <h3>选择时间格</h3>\n              <p class=\"hint\">点员工对应的时间段后，在这里选择休息、待命或具体区域。</p>\n            </section>\n            <div class=\"row-actions\">\n              <button class=\"small-button\" type=\"button\" @click=\"confirmBossSchedule\">确定排班</button>\n            </div>\n          </template>\n\n          <template v-else-if=\"bossView === 'areas'\">\n            <div class=\"data-grid two\">\n              <section v-for=\"area in bossState.区域\" :key=\"area.名称\" class=\"data-line\">\n                <div class=\"line-head\">\n                  <h3>{{ area.名称 }}</h3>\n                  <span class=\"tag\" :class=\"{ warn: area.名称 === bossState.地点 }\">{{ area.客人 }}人</span>\n                </div>\n                <p>{{ area.说明 }}</p>\n                <p>在岗：{{ area.员工.join('、') || '暂无' }}</p>\n                <div class=\"row-actions\">\n                  <button class=\"small-button\" type=\"button\" @click=\"goBossArea(area.名称)\">\n                    {{ area.名称 === bossState.地点 ? '已在这里' : '前往' }}\n                  </button>\n                </div>\n              </section>\n            </div>\n          </template>\n\n          <template v-else-if=\"bossView === 'employees'\">\n            <div class=\"data-grid two\">\n              <section v-for=\"employee in bossState.员工\" :key=\"employee.姓名\" class=\"data-line\">\n                <div class=\"line-head\">\n                  <h3>{{ employee.姓名 }}</h3>\n                  <span>\n                    <span class=\"tag\">{{ employee.评级 }}</span>\n                    <span class=\"tag\" :class=\"{ warn: employee.状态 === '指名中' }\">{{ employee.状态 }}</span>\n                  </span>\n                </div>\n                <p>{{ employee.区域 }} · 日薪 {{ yuan(employee.日薪) }} · 评分 {{ employee.评分 }}</p>\n                <div class=\"thin-meter\" :style=\"{ '--value': `${employee.评分}%` }\"><span /></div>\n                <p>满意 {{ employee.满意度 }} · 疲劳 {{ employee.疲劳 }} · 今日个人收入 {{ yuan(employee.个人收入) }}</p>\n                <div class=\"thin-meter danger-aware\" :style=\"{ '--value': `${employee.离职风险}%` }\"><span /></div>\n                <p>离职风险 {{ employee.离职风险 }} · 期望日薪 {{ yuan(employee.期望日薪) }}</p>\n                <p>服务 {{ employee.服务次数 }} · 指名 {{ employee.指名次数 }} · 额外结果 {{ employee.额外结果次数 }}</p>\n                <div class=\"row-actions\">\n                  <template v-if=\"employee.区域 === bossState.地点\">\n                    <button class=\"small-button\" type=\"button\" @click=\"talkBossEmployee(employee.姓名)\">交谈</button>\n                    <button class=\"small-button\" type=\"button\" @click=\"raiseBossSalary(employee.姓名)\">加日薪</button>\n                    <button class=\"small-button\" type=\"button\" @click=\"checkBossService(employee.姓名)\">查看服务</button>\n                  </template>\n                  <button v-else class=\"small-button\" type=\"button\" @click=\"goBossEmployee(employee.姓名)\">前往</button>\n                </div>\n              </section>\n            </div>\n          </template>\n\n          <template v-else-if=\"bossView === 'projects'\">\n            <div class=\"data-grid two\">\n              <section v-for=\"project in bossState.项目\" :key=\"project.名称\" class=\"data-line\">\n                <div class=\"line-head\">\n                  <h3>{{ project.名称 }}</h3>\n                  <span class=\"tag\" :class=\"{ good: project.推荐值 >= 86 }\">{{ project.热度 }}</span>\n                </div>\n                <p>基础价格 {{ yuan(project.基础价格) }} · 评分 {{ project.评分 }}</p>\n                <div class=\"thin-meter\" :style=\"{ '--value': `${project.推荐值}%` }\"><span /></div>\n                <p>{{ project.设施需求 }} · 今日订单 {{ project.今日订单 }}/{{ project.容量 }} · 推荐值 {{ percent(project.推荐值 / 100) }}。</p>\n                <div class=\"row-actions\">\n                  <button class=\"small-button\" type=\"button\" @click=\"adjustBossProject(project.名称, 'down')\">降价</button>\n                  <button class=\"small-button\" type=\"button\" @click=\"adjustBossProject(project.名称, 'up')\">涨价</button>\n                  <button class=\"small-button\" type=\"button\" @click=\"investBossQuality(project.名称)\">品质投入</button>\n                </div>\n              </section>\n            </div>\n          </template>\n\n          <template v-else-if=\"bossView === 'nominations'\">\n            <div class=\"data-grid two\">\n              <section v-for=\"item in bossState.指名\" :key=\"`${item.员工}-${item.客人}`\" class=\"data-line\">\n                <div class=\"line-head\">\n                  <h3>{{ item.员工 }}</h3>\n                  <span class=\"tag warn\">剩余{{ item.剩余天数 }}天</span>\n                </div>\n                <p>{{ item.客人 }} · {{ item.区域 }}</p>\n                <p>员工个人收入 {{ yuan(item.预计收入) }}，含指名费 {{ yuan(item.每日指名费) }} 和预估小费 {{ yuan(item.预计小费) }}。</p>\n                <div class=\"row-actions\">\n                  <button class=\"small-button\" type=\"button\" @click=\"checkBossService(item.员工)\">查看服务</button>\n                </div>\n              </section>\n            </div>\n          </template>\n\n          <template v-else-if=\"bossView === 'market'\">\n            <div class=\"data-grid two\">\n              <section v-for=\"item in bossState.人才市场\" :key=\"item.姓名\" class=\"data-line\">\n                <div class=\"line-head\">\n                  <h3>{{ item.姓名 }}</h3>\n                  <span class=\"tag\">{{ item.类型 }}</span>\n                </div>\n                <p>{{ item.说明 }}</p>\n                <p>评级 {{ item.评级 }} · 市场价格 {{ yuan(item.市场价格) }} · 期望日薪 {{ yuan(item.期望日薪) }}</p>\n                <div class=\"row-actions\">\n                  <button class=\"small-button\" type=\"button\" @click=\"talkBossMarket(item.姓名)\">交流</button>\n                  <button class=\"small-button\" type=\"button\" @click=\"buyBossMarket(item.姓名)\">买入</button>\n                </div>\n              </section>\n            </div>\n          </template>\n\n          <template v-else-if=\"bossView === 'recruit'\">\n            <div class=\"data-grid two\">\n              <section class=\"metric-line\">\n                <span>刷新倒计时</span>\n                <strong>{{ bossState.招聘.刷新倒计时 }}</strong>\n                <p>默认每 12 小时刷新一个候选。</p>\n              </section>\n              <section class=\"metric-line\">\n                <span>当前候选</span>\n                <strong>{{ bossState.招聘.姓名 }}</strong>\n                <p>拒绝记录 {{ bossState.招聘.拒绝记录 }}，下次出现会换新的自我介绍。</p>\n              </section>\n            </div>\n            <section class=\"data-line spaced\">\n              <div class=\"line-head\">\n                <h3>{{ bossState.招聘.姓名 }}</h3>\n                <span class=\"tag\">期望日薪 {{ yuan(bossState.招聘.期望日薪) }}</span>\n              </div>\n              <p>{{ bossState.招聘.说明 }}</p>\n              <div class=\"row-actions\">\n                <button class=\"small-button\" type=\"button\" @click=\"talkBossRecruit\">面试</button>\n                <button class=\"small-button\" type=\"button\" @click=\"hireBossRecruit\">录用</button>\n                <button class=\"small-button\" type=\"button\" @click=\"rejectBossRecruit\">拒绝</button>\n              </div>\n            </section>\n          </template>\n\n          <template v-else-if=\"bossView === 'facilities'\">\n            <div class=\"data-grid three\">\n              <section class=\"metric-line\">\n                <span>接待上限</span>\n                <strong>{{ bossCapacity }}</strong>\n                <p>由当前全部建设等级、维护和可开放区域共同影响。</p>\n              </section>\n              <section class=\"metric-line\">\n                <span>维护度</span>\n                <strong>{{ bossState.基建.维护度 }}</strong>\n                <p>当前维护费用 {{ yuan(bossMaintenanceCost) }}。</p>\n              </section>\n              <section class=\"metric-line\">\n                <span>已开放</span>\n                <strong>{{ bossUnlockedInfrastructureItems.length }}</strong>\n                <p>区域和项目会跟随验收结果开放。</p>\n              </section>\n            </div>\n            <div class=\"data-grid two spaced\">\n              <section v-for=\"item in bossInfrastructureItems\" :key=\"item.key\" class=\"data-line\">\n                <div class=\"line-head\">\n                  <h3>{{ item.label }}</h3>\n                  <span class=\"tag\" :class=\"{ good: item.isMaxed, warn: item.inProgress }\">\n                    {{ item.inProgress ? '施工中' : item.isMaxed ? '满级' : `等级 ${item.level}` }}\n                  </span>\n                </div>\n                <p>{{ item.note }}</p>\n                <p v-if=\"item.isMaxed\">这条路线已经完成，后续只需要维护。</p>\n                <p v-else>升到 {{ item.level + 1 }} 级：总费用 {{ yuan(item.cost) }}，预计 {{ item.days }} 天。</p>\n                <p v-if=\"item.nextUnlocks.length\">\n                  相关目标：{{ item.nextUnlocks.map(unlock => unlock.名称).join('、') }}\n                </p>\n                <p v-else-if=\"!item.isMaxed\">下一级主要提高容量、舒适度和经营稳定性。</p>\n                <div class=\"row-actions\">\n                  <button class=\"small-button\" type=\"button\" :disabled=\"item.isMaxed || item.inProgress\" @click=\"upgradeBossFacility(item.key)\">\n                    {{ item.isMaxed ? '完成' : item.inProgress ? '施工中' : '开工' }}\n                  </button>\n                </div>\n              </section>\n              <section class=\"data-line\">\n                <div class=\"line-head\">\n                  <h3>环境维护</h3>\n                  <span class=\"tag\" :class=\"{ warn: bossState.基建.维护度 < 65, good: bossState.基建.维护度 >= 86 }\">\n                    {{ bossState.基建.维护度 }}\n                  </span>\n                </div>\n                <p>维护越低，客人评分、项目推荐和员工状态越容易下滑。</p>\n                <div class=\"thin-meter\" :style=\"{ '--value': `${bossState.基建.维护度}%` }\"><span /></div>\n                <div class=\"row-actions\">\n                  <button class=\"small-button\" type=\"button\" @click=\"maintainBossFacilities\">维护</button>\n                </div>\n              </section>\n            </div>\n            <section class=\"building-board spaced\">\n              <header class=\"building-board-head\">\n                <div>\n                  <h3>建筑扩建</h3>\n                  <p>拖动画面查看完整路线；点击建筑查看费用、工期和开放条件。</p>\n                </div>\n                <div class=\"row-actions compact\">\n                  <span class=\"tag good\">已建成 {{ bossBuiltBuildingCount }}</span>\n                  <span class=\"tag\">总数 {{ bossBuildingItems.length }}</span>\n                  <button class=\"small-button\" type=\"button\" @click=\"resetBossBuildingPan\">居中</button>\n                </div>\n              </header>\n\n              <div class=\"building-tree-panel\">\n                <div\n                  class=\"building-map\"\n                  role=\"application\"\n                  aria-label=\"建筑扩建路线\"\n                  @pointerdown=\"startBossBuildingPan\"\n                  @pointermove=\"moveBossBuildingPan\"\n                  @pointerup=\"endBossBuildingPan\"\n                  @pointerleave=\"endBossBuildingPan\"\n                >\n                  <div\n                    class=\"building-map-canvas\"\n                    :style=\"{ width: `${bossBuildingMapSize.width}px`, height: `${bossBuildingMapSize.height}px`, transform: `translate(${bossBuildingPan.x}px, ${bossBuildingPan.y}px)` }\"\n                  >\n                    <svg class=\"building-links\" :viewBox=\"`0 0 ${bossBuildingMapSize.width} ${bossBuildingMapSize.height}`\" aria-hidden=\"true\">\n                      <line\n                        v-for=\"line in bossBuildingLines\"\n                        :key=\"line.id\"\n                        :x1=\"line.x1\"\n                        :y1=\"line.y1\"\n                        :x2=\"line.x2\"\n                        :y2=\"line.y2\"\n                        :class=\"line.statusClass\"\n                      />\n                    </svg>\n\n                    <button\n                      v-for=\"node in bossBuildingNodes\"\n                      :key=\"node.id\"\n                      class=\"building-node\"\n                      :class=\"[node.statusClass, { 'is-selected': bossSelectedBuilding?.id === node.id }]\"\n                      type=\"button\"\n                      :style=\"{ left: `${node.x}px`, top: `${node.y}px` }\"\n                      @pointerdown.stop\n                      @click=\"bossSelectedBuildingId = node.id\"\n                    >\n                      <span>{{ node.分类 }}</span>\n                      <strong>{{ node.名称 }}</strong>\n                      <small>{{ node.levelText }}</small>\n                    </button>\n                  </div>\n                </div>\n\n                <aside v-if=\"bossSelectedBuilding\" class=\"building-detail\">\n                  <div class=\"line-head\">\n                    <h3>{{ bossSelectedBuilding.名称 }}</h3>\n                    <span class=\"tag\" :class=\"{ good: bossSelectedBuilding.状态 === '已建成', warn: bossSelectedBuilding.状态 === '施工中' || bossSelectedBuilding.状态 === '待验收' }\">\n                      {{ bossSelectedBuilding.levelText }}\n                    </span>\n                  </div>\n                  <p>{{ bossSelectedBuilding.说明 }}</p>\n                  <p>条件：{{ bossSelectedBuilding.requirementText }}</p>\n                  <p v-if=\"bossSelectedBuilding.missing.length\">还差：{{ bossSelectedBuilding.missing.join('、') }}</p>\n                  <p v-else-if=\"bossSelectedBuilding.状态 === '已建成' && bossSelectedBuilding.等级 >= bossSelectedBuilding.maxLevel\">这项建筑已经到达最高等级。</p>\n                  <p v-else-if=\"bossSelectedBuilding.状态 === '施工中'\">工程正在推进，日结后会减少剩余天数。</p>\n                  <p v-else-if=\"bossSelectedBuilding.状态 === '待验收'\">工程已经完成，验收后才会正式生效。</p>\n                  <p v-else>预计费用 {{ yuan(bossSelectedBuilding.cost) }}，工期 {{ bossSelectedBuilding.days }} 天。</p>\n                  <p>{{ bossSelectedBuilding.effectText }}</p>\n                  <div class=\"row-actions\">\n                    <button\n                      class=\"small-button\"\n                      type=\"button\"\n                      :disabled=\"!bossSelectedBuildingCanAct\"\n                      @click=\"handleBossSelectedBuildingAction\"\n                    >\n                      {{ bossSelectedBuildingActionText }}\n                    </button>\n                  </div>\n                </aside>\n              </div>\n            </section>\n            <div class=\"data-grid two spaced\">\n              <section class=\"data-line\">\n                <div class=\"line-head\">\n                  <h3>已开放内容</h3>\n                  <span class=\"tag good\">{{ bossUnlockedInfrastructureItems.length }}</span>\n                </div>\n                <div class=\"ledger-list\">\n                  <p v-for=\"item in bossUnlockedInfrastructureItems\" :key=\"item.id\">\n                    {{ item.名称 }} · {{ item.分类 }} · {{ item.说明 }}\n                  </p>\n                </div>\n              </section>\n              <section class=\"data-line\">\n                <div class=\"line-head\">\n                  <h3>下一批目标</h3>\n                  <span class=\"tag\">{{ bossUpcomingInfrastructureItems.length }}</span>\n                </div>\n                <div class=\"ledger-list\">\n                  <p v-for=\"item in bossUpcomingInfrastructureItems\" :key=\"item.id\">\n                    {{ item.名称 }} · {{ item.分类 }} · {{ item.说明 }}\n                  </p>\n                  <p v-if=\"!bossUpcomingInfrastructureItems.length\">目前没有临近开放目标。</p>\n                </div>\n              </section>\n            </div>\n            <section class=\"data-line spaced\">\n              <div class=\"line-head\">\n                <h3>工程进度</h3>\n                <span class=\"tag\">{{ bossState.工程.length }}</span>\n              </div>\n              <template v-if=\"bossState.工程.length\">\n                <div class=\"ledger-list\">\n                  <p v-for=\"project in bossState.工程\" :key=\"project.id\">\n                    {{ project.名称 || getBossInfrastructureLabel(project.设施) }} {{ project.当前等级 }}→{{ project.目标等级 }} · {{ project.状态 }} · 剩余 {{ project.剩余天数 }} 天 · 每日 {{ yuan(project.每日消耗) }}\n                    <button v-if=\"project.状态 === '待验收'\" class=\"inline-action\" type=\"button\" @click=\"acceptBossProject(project.id)\">验收</button>\n                  </p>\n                </div>\n              </template>\n              <p v-else>当前没有施工中的工程。</p>\n            </section>\n          </template>\n\n          <template v-else-if=\"bossView === 'settlement'\">\n            <div class=\"data-grid two\">\n              <section class=\"metric-line\">\n                <span>营业状态</span>\n                <strong>{{ bossState.营业状态 }}</strong>\n                <p>{{ bossBusinessStatusText }}</p>\n              </section>\n              <section class=\"metric-line\">\n                <span>今日修正</span>\n                <strong>{{ bossState.节假日.名称 }}</strong>\n                <p>客流 {{ percent(bossState.节假日.客流倍率) }} · 价格 {{ percent(bossState.节假日.价格倍率) }} · 活动 {{ percent(bossState.节假日.活动倍率) }}</p>\n              </section>\n            </div>\n            <div class=\"data-grid three\">\n              <section class=\"metric-line\">\n                <span>收入</span>\n                <strong>{{ yuan(bossState.结算.收入) }}</strong>\n                <p>到店、项目、住宿包场和活动套餐。</p>\n              </section>\n              <section class=\"metric-line\">\n                <span>支出</span>\n                <strong>{{ yuan(bossState.结算.支出) }}</strong>\n                <p>日薪、运营、维护和服务准备。</p>\n              </section>\n              <section class=\"metric-line\">\n                <span>毛利</span>\n                <strong>{{ yuan(bossState.结算.毛利) }}</strong>\n                <p>结算后同步资金。</p>\n              </section>\n            </div>\n            <div class=\"data-grid two spaced\">\n              <section class=\"metric-line\">\n                <span>员工个人收入</span>\n                <strong>{{ yuan(bossState.结算.员工收入合计) }}</strong>\n                <p>指名费和小费归员工个人，不进入店铺资金。</p>\n              </section>\n              <section class=\"metric-line\">\n                <span>明日预测</span>\n                <strong>{{ bossState.结算.明日预测.客流 }}</strong>\n                <p>评分 {{ bossState.结算.明日预测.店铺评分 }}，平均满意 {{ bossState.结算.明日预测.平均满意度 }}。</p>\n              </section>\n            </div>\n            <section class=\"data-line spaced\">\n              <div class=\"line-head\">\n                <h3>快速功能</h3>\n                <span class=\"tag\">{{ bossState.营业状态 }}</span>\n              </div>\n              <p>暂停只停止新增接客；今日停业会让当天收入归零但仍有基础支出；休息一天会直接推进日期并扣最低成本。</p>\n              <p>宣传：{{ bossActiveCampaignText }}。品质投入：{{ bossActiveQualityText }}。员工福利剩余 {{ bossState.员工福利.剩余天数 }} 天。</p>\n              <div class=\"row-actions\">\n                <button class=\"small-button\" type=\"button\" @click=\"toggleBossPause\">\n                  {{ bossState.营业状态 === '暂停营业' ? '恢复营业' : '暂停营业' }}\n                </button>\n                <button class=\"small-button\" type=\"button\" @click=\"closeBossToday\">今日停业</button>\n                <button class=\"small-button\" type=\"button\" @click=\"restBossToday\">休息一天</button>\n                <button class=\"small-button\" type=\"button\" @click=\"startBossCampaign\">宣传</button>\n                <button class=\"small-button\" type=\"button\" @click=\"investBossCare\">员工福利</button>\n              </div>\n            </section>\n            <section class=\"data-line spaced\">\n              <div class=\"line-head\">\n                <h3>今日结算</h3>\n                <button class=\"small-button\" type=\"button\" @click=\"closeBossDay\">执行</button>\n              </div>\n              <p>执行后时间推进到 00:00，今日内容刷新，跨天指名减少剩余天数。</p>\n            </section>\n            <div class=\"data-grid two spaced\">\n              <section class=\"data-line\">\n                <div class=\"line-head\">\n                  <h3>支出明细</h3>\n                  <span class=\"tag\">{{ yuan(bossState.结算.支出) }}</span>\n                </div>\n                <p>员工工资 {{ yuan(bossState.结算.支出明细.日薪) }} · 固定运营 {{ yuan(bossState.结算.支出明细.固定运营) }}</p>\n                <p>设施维护 {{ yuan(bossState.结算.支出明细.设施维护) }} · 服务准备 {{ yuan(bossState.结算.支出明细.服务准备) }}</p>\n                <p>工程消耗 {{ yuan(bossState.结算.支出明细.工程消耗) }}</p>\n              </section>\n              <section class=\"data-line\">\n                <div class=\"line-head\">\n                  <h3>员工日结</h3>\n                  <span class=\"tag\">{{ bossState.结算.员工日结.length }}</span>\n                </div>\n                <div class=\"ledger-list\">\n                  <p v-for=\"report in bossState.结算.员工日结\" :key=\"report.员工\">\n                    {{ report.员工 }} · {{ report.角色 }} · 工资 {{ yuan(report.工资) }} · 疲劳 {{ signedNumber(report.疲劳变化) }}\n                  </p>\n                </div>\n              </section>\n            </div>\n            <section class=\"data-line spaced\">\n              <div class=\"line-head\">\n                <h3>今日账本</h3>\n                <span class=\"tag\">{{ bossState.结算.状态 }}</span>\n              </div>\n              <div class=\"ledger-list\">\n                <p v-for=\"entry in bossState.结算.流水\" :key=\"entry.id\">\n                  {{ entry.名称 }} · {{ entry.类型 }} {{ yuan(entry.金额) }} · 资金 {{ signedYuan(entry.资金变动) }}\n                </p>\n              </div>\n            </section>\n          </template>\n        </div>\n      </article>\n    </section>\n\n    <section class=\"dialogue\">\n      <div class=\"nameplate\">{{ dialogueSpeakerName }}</div>\n      <div class=\"dialogue-strip\">\n        <p class=\"dialogue-text\">{{ playShellText }}</p>\n      </div>\n    </section>\n\n    <section v-if=\"airpState\" class=\"scene-input\" aria-label=\"现场输入\">\n      <header>\n        <div>\n          <strong>{{ airpState.title }}</strong>\n          <span>{{ airpState.note }}</span>\n        </div>\n        <button class=\"inline-action\" type=\"button\" :disabled=\"airpSubmitting\" @click=\"closeAirpScene\">离开</button>\n      </header>\n      <div class=\"scene-input-row\">\n        <textarea\n          v-model=\"airpInput\"\n          :placeholder=\"airpState.placeholder\"\n          :disabled=\"airpSubmitting\"\n          @keydown.ctrl.enter.prevent=\"submitAirpInput\"\n          @keydown.meta.enter.prevent=\"submitAirpInput\"\n        />\n        <button class=\"scene-send\" type=\"button\" :disabled=\"airpSubmitting || !airpInput.trim()\" @click=\"submitAirpInput\">\n          {{ airpSubmitting ? '等待' : '发送' }}\n        </button>\n      </div>\n    </section>\n\n    <div class=\"toast\" :class=\"{ 'is-show': toastText }\">{{ toastText }}</div>\n  </main>\n\n  <section v-if=\"confirmState\" class=\"confirm-layer\" aria-label=\"操作确认\">\n    <div class=\"confirm-backdrop\" />\n    <div class=\"confirm-dialog\">\n      <small>未开之花</small>\n      <h2>{{ confirmState.title }}</h2>\n      <p>{{ confirmState.message }}</p>\n      <div class=\"confirm-actions\">\n        <button class=\"setting-choice\" type=\"button\" @click=\"resolveConfirm(false)\">取消</button>\n        <button class=\"setting-choice is-primary\" type=\"button\" @click=\"resolveConfirm(true)\">确认</button>\n      </div>\n    </div>\n  </section>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, onMounted, ref } from 'vue';\nimport type { TangquanLogEntry } from '../../debug/logger';\nimport type { TangquanSaveRuntime } from '../../save/saveRuntime';\nimport type { TangquanUserGenderKey, TangquanUserProfileInput } from '../../save/userProfileWorldbook';\nimport type { TangquanPlayMode, TangquanSaveInspection, TangquanSaveSlotMeta } from '../../save/worldbookSave';\nimport titleBgUrl from '../../../../assets/onsen-refactor/title-night-entrance.png?url';\nimport bossBgUrl from '../../../../assets/onsen-refactor/boss-lobby.png?url';\nimport customerBgUrl from '../../../../assets/onsen-refactor/customer-private-bath.png?url';\nimport waiterBgUrl from '../../../../assets/onsen-refactor/waiter-staff-room.png?url';\nimport staffSpriteUrl from '../../../../assets/onsen-refactor/staff-sprite-transparent.png?url';\nimport {\n  acceptBossConstructionProject,\n  adjustBossProjectPrice,\n  buyBossMarketCandidate,\n  cloneBossPageState,\n  closeBossBusinessToday,\n  confirmBossScheduleState,\n  getBossBuildingCatalog,\n  getBossAverageSatisfaction,\n  getBossInfrastructureCatalog,\n  getBossInfrastructureCapacity,\n  getBossInfrastructureLabel,\n  getBossInfrastructureUpgradeCost,\n  getBossMaintenanceCost,\n  getBossUnlockedInfrastructureItems,\n  getBossUpcomingInfrastructureItems,\n  hireBossRecruitCandidate,\n  investBossProjectQuality,\n  investBossStaffCare,\n  maintainBossInfrastructure,\n  makeBossPageState,\n  normalizeBossPageState,\n  pauseBossBusiness,\n  raiseBossEmployeeSalary,\n  recalculateBossState,\n  rejectBossRecruitCandidate,\n  restBossOneDay,\n  resumeBossBusiness,\n  settleBossDay,\n  startBossBuildingProject,\n  startBossMarketingCampaign,\n  upgradeBossInfrastructure,\n  type BossBuildingCatalogItem,\n  type BossEmployee,\n  type BossInfrastructureCatalogItem,\n  type BossInfrastructureKey,\n  type BossInfrastructureUnlock,\n  type BossPageState,\n  type BossProject,\n} from './bossEconomy';\nimport {\n  cloneMvuBlockStore,\n  composeStatDataWithBlocks,\n  deactivateStatDataBlocks,\n  makeBossCommonStatData,\n  makeAreaEntryContent,\n  makeCandidateEntryContent,\n  makeEmployeeEntryContent,\n  makeGuestEntryContent,\n  makeMvuBlockStore,\n  makeProjectEntryContent,\n  normalizeMvuBlockStore,\n  saveActiveBlocksFromStatData,\n  type BossMvuBlockContext,\n  type TangquanMvuBlockId,\n  type TangquanMvuBlockStore,\n} from './mvuBlocks';\nimport { getTangquanUiSettings, patchTangquanUiSettings, type TangquanUiSettings } from './settings';\nimport type { TangquanGameUiServices } from './types';\nimport {\n  makeTangquanBuildingEntryId,\n  makeTangquanInfrastructureEntryId,\n  makeTangquanProjectEntryId,\n  TANGQUAN_AREA_TO_BUILDING,\n  TANGQUAN_PROJECT_TO_BUILDING,\n} from '../../worldbook/worldbookEntryCatalog';\n\ntype Mode = Exclude<TangquanPlayMode, '未选择'>;\ntype ActivePage = 'home' | 'play';\ntype TitlePanel = 'landing' | 'modes' | 'load' | 'profile' | 'settings' | 'logs';\ntype TitleMenuKey = 'start' | 'continue' | 'load' | 'settings' | 'logs';\ntype SavePanelContext = 'title' | 'play';\ntype SettingKey = keyof TangquanUiSettings;\ntype BossMenuView =\n  | 'overview'\n  | 'schedule'\n  | 'areas'\n  | 'employees'\n  | 'projects'\n  | 'nominations'\n  | 'market'\n  | 'recruit'\n  | 'facilities'\n  | 'settlement';\ntype ConfirmState = {\n  title: string;\n  message: string;\n};\ntype BossShiftSelection = {\n  name: string;\n  index: number;\n};\ntype BossBuildingNode = BossBuildingCatalogItem & {\n  x: number;\n  y: number;\n  statusClass: string;\n  levelText: string;\n  requirementText: string;\n  actionText: string;\n  canAct: boolean;\n  effectText: string;\n};\ntype BossBuildingLine = {\n  id: string;\n  x1: number;\n  y1: number;\n  x2: number;\n  y2: number;\n  statusClass: string;\n};\ntype BossBuildingDragState = {\n  pointerId: number;\n  startX: number;\n  startY: number;\n  originX: number;\n  originY: number;\n};\ntype AirpSceneState = {\n  mode: Mode;\n  title: string;\n  note: string;\n  speaker: string;\n  line: string;\n  placeholder: string;\n  scene: Record<string, unknown>;\n  entryIds: string[];\n  entryContentMap?: Record<string, string>;\n  blockIds?: TangquanMvuBlockId[];\n  blockContext?: BossMvuBlockContext;\n};\n\nconst SAVE_SLOT_COUNT = 12;\nconst SAVE_SLOT_IDS = Array.from({ length: SAVE_SLOT_COUNT }, (_, index) => `slot-${String(index + 1).padStart(2, '0')}`);\nconst BOSS_BUILDING_BRANCH_ORDER: BossInfrastructureKey[] = ['前台接待', '更衣清洗', '汤池', '休息区', '理疗区', '包间', '餐饮区', '客房', '庭院', '员工休息室', '后勤', '占地规模'];\nconst BOSS_BUILDING_ANCHORS: Record<BossInfrastructureKey, string> = {\n  占地规模: 'area_lobby',\n  前台接待: 'area_lobby',\n  更衣清洗: 'area_changing',\n  汤池: 'area_indoor_bath',\n  休息区: 'area_rest_hall',\n  理疗区: 'area_massage',\n  包间: 'area_basic_room',\n  餐饮区: 'area_tea_corner',\n  客房: 'area_guest_room',\n  庭院: 'area_garden_path',\n  员工休息室: 'area_staff_room',\n  后勤: 'area_office',\n};\nconst BOSS_BUILDING_MAP_SIZE = { width: 1440, height: 1080 };\n\nconst props = defineProps<{\n  services: TangquanGameUiServices;\n  onClose: () => void;\n}>();\n\nconst modes: { key: Mode; mark: string; title: string; note: string }[] = [\n  { key: '老板', mark: '店', title: '经营者', note: '你扮演未开之花的经营者，安排排班、人才、收入结算，也可以亲自走进现场。' },\n  { key: '游客', mark: '客', title: '到店客人', note: '你扮演来店消费的客人，以指名、服务、好感、联系人和私下邀约推进。' },\n  { key: '服务员', mark: '侍', title: '在店服务员', note: '你扮演在店工作的服务员，接班接待、获得评价，并推动自己的评级变化。' },\n];\n\nconst bossTabs: { key: BossMenuView; title: string; note: string }[] = [\n  { key: 'overview', title: '总览', note: '今天最重要的经营信息。' },\n  { key: 'schedule', title: '排班', note: '点击员工对应时间段后选择位置或休息。' },\n  { key: 'areas', title: '区域', note: '查看各区域客流和在岗员工。' },\n  { key: 'employees', title: '员工', note: '同区域员工可交谈、加日薪或查看服务。' },\n  { key: 'projects', title: '项目', note: '项目推荐值影响后续客流和价格调整。' },\n  { key: 'nominations', title: '指名', note: '跨天指名按剩余天数延续。' },\n  { key: 'market', title: '人才市场', note: '查看可买入的人才。' },\n  { key: 'recruit', title: '招聘', note: '候选默认每 12 小时刷新。' },\n  { key: 'facilities', title: '基建', note: '扩建设施、维护环境和提升接待上限。' },\n  { key: 'settlement', title: '结算', note: '结算今日经营并推进到 00:00。' },\n];\n\nconst profileGenderOptions: { key: TangquanUserGenderKey; label: string }[] = [\n  { key: '男', label: '男' },\n  { key: '女', label: '女' },\n  { key: '扶她', label: '扶她' },\n  { key: '男娘', label: '男娘' },\n  { key: '双性', label: '双性' },\n  { key: '无性', label: '无性' },\n  { key: '自定义', label: '自定义' },\n];\n\nconst settingGroups: {\n  key: SettingKey;\n  title: string;\n  note: string;\n  options: { value: string; label: string }[];\n}[] = [\n  {\n    key: 'fontSize',\n    title: '字号',\n    note: '阅读文字大小',\n    options: [\n      { value: 'small', label: '小' },\n      { value: 'standard', label: '标准' },\n      { value: 'large', label: '大' },\n      { value: 'xlarge', label: '超大' },\n    ],\n  },\n  {\n    key: 'fontFamily',\n    title: '字体风格',\n    note: '氛围或清晰优先',\n    options: [\n      { value: 'default', label: '默认' },\n      { value: 'elegant', label: '雅致' },\n      { value: 'clear', label: '清晰' },\n    ],\n  },\n  {\n    key: 'layout',\n    title: '界面布局',\n    note: '自动适配不同屏幕',\n    options: [\n      { value: 'auto', label: '自动' },\n      { value: 'compact', label: '紧凑' },\n      { value: 'wide', label: '宽松' },\n    ],\n  },\n  {\n    key: 'panel',\n    title: '对话框透明度',\n    note: '文字优先或画面优先',\n    options: [\n      { value: 'clear', label: '清晰' },\n      { value: 'standard', label: '标准' },\n      { value: 'soft', label: '通透' },\n    ],\n  },\n  {\n    key: 'developerLog',\n    title: '运行日志',\n    note: '开发期排查用',\n    options: [\n      { value: 'show', label: '显示' },\n      { value: 'hide', label: '隐藏' },\n    ],\n  },\n];\n\nconst settings = ref<TangquanUiSettings>(getTangquanUiSettings());\nconst runtime = ref<TangquanSaveRuntime>(props.services.save.getRuntime());\nconst activePage = ref<ActivePage>('home');\nconst activePanel = ref<TitlePanel>('landing');\nconst savePanelContext = ref<SavePanelContext>('title');\nconst selectedMode = ref<Mode>(runtime.value.activeMode === '未选择' ? '老板' : runtime.value.activeMode);\nconst activeMode = ref<Mode>(selectedMode.value);\nconst currentSlotLabel = ref('新存档');\nconst slots = ref<TangquanSaveSlotMeta[]>([]);\nconst selectedSlotId = ref(SAVE_SLOT_IDS[0]);\nconst inspection = ref<TangquanSaveInspection | null>(null);\nconst showSaveTools = ref(false);\nconst logEntries = ref<TangquanLogEntry[]>([]);\nconst profileName = ref('');\nconst profileGenderKey = ref<TangquanUserGenderKey>('男');\nconst profileGenderText = ref('');\nconst profileDescription = ref('');\nconst importInput = ref<HTMLInputElement | null>(null);\nconst confirmState = ref<ConfirmState | null>(null);\nconst bossState = ref<BossPageState>(makeBossPageState());\nconst bossView = ref<BossMenuView>('overview');\nconst bossMenuOpen = ref(false);\nconst bossActiveShift = ref<BossShiftSelection | null>(null);\nconst bossSelectedBuildingId = ref('');\nconst bossBuildingPan = ref({ x: 0, y: 0 });\nconst bossBuildingDrag = ref<BossBuildingDragState | null>(null);\nconst bossSpeakerName = ref('未开之花');\nconst bossDialogueText = ref('店铺已经开灯，今天的经营、排班、现场互动会从这里继续。');\nconst airpState = ref<AirpSceneState | null>(null);\nconst airpInput = ref('');\nconst airpSubmitting = ref(false);\nconst activeTemporaryEntryIds = ref<string[]>([]);\nconst mvuBlockStore = ref<TangquanMvuBlockStore>(makeMvuBlockStore());\nconst busy = ref(false);\nconst toastText = ref('');\nlet toastTimer = 0;\nlet pendingConfirmResolve: ((value: boolean) => void) | null = null;\n\nconst titleMenuItems = computed(() => {\n  const items: { key: TitleMenuKey; label: string }[] = [\n    { key: 'start', label: '开始游戏' },\n    { key: 'continue', label: '继续游戏' },\n    { key: 'load', label: '存档' },\n    { key: 'settings', label: '设置' },\n  ];\n  if (settings.value.developerLog === 'show') {\n    items.push({ key: 'logs', label: '日志' });\n  }\n  return items;\n});\n\nconst slotViews = computed(() =>\n  SAVE_SLOT_IDS.map((id, index) => ({\n    id,\n    label: `存档 ${String(index + 1).padStart(2, '0')}`,\n    meta: slots.value.find(slot => slot.slotId === id) ?? null,\n  })),\n);\n\nconst selectedSlotMeta = computed(() => slots.value.find(slot => slot.slotId === selectedSlotId.value) ?? null);\n\nconst isBossMenuVisible = computed(() => activeMode.value === '老板' && bossMenuOpen.value);\n\nconst activeBossTab = computed(() => bossTabs.find(tab => tab.key === bossView.value) ?? bossTabs[0]);\n\nconst bossPayroll = computed(() => bossState.value.员工.reduce((sum, employee) => sum + employee.日薪, 0));\n\nconst bossHotProject = computed(() => [...bossState.value.项目].sort((a, b) => b.推荐值 - a.推荐值)[0] ?? null);\n\nconst bossCurrentStaff = computed(() => bossState.value.员工.filter(employee => employee.区域 === bossState.value.地点));\n\nconst bossCurrentStaffText = computed(() => bossCurrentStaff.value.map(employee => employee.姓名).join('、') || '暂无');\n\nconst bossScheduleChoices = computed(() => ['休息', '待命', ...bossState.value.区域.map(area => area.名称), '清洁']);\n\nconst bossAverageSatisfaction = computed(() => getBossAverageSatisfaction(bossState.value));\n\nconst bossCapacity = computed(() => getBossInfrastructureCapacity(bossState.value));\n\nconst bossMaintenanceCost = computed(() => getBossMaintenanceCost(bossState.value));\n\nconst bossBusinessStatusText = computed(() => {\n  if (bossState.value.营业状态 === '暂停营业') {\n    return `暂停前客流 ${bossState.value.暂停保留客流}，不会继续增加新客。`;\n  }\n  if (bossState.value.营业状态 === '今日停业') {\n    return '今日不接待客人，结算时没有营业收入。';\n  }\n  return '正常接待客人，客流和项目订单按当前公式计算。';\n});\n\nconst bossInfrastructureItems = computed<BossInfrastructureCatalogItem[]>(() => getBossInfrastructureCatalog(bossState.value));\n\nconst bossBuildingItems = computed<BossBuildingCatalogItem[]>(() => getBossBuildingCatalog(bossState.value));\n\nconst bossBuildingMapSize = computed(() => BOSS_BUILDING_MAP_SIZE);\n\nconst bossBuildingNodes = computed<BossBuildingNode[]>(() => makeBossBuildingNodes(bossBuildingItems.value));\n\nconst bossBuildingLines = computed<BossBuildingLine[]>(() => makeBossBuildingLines(bossBuildingNodes.value));\n\nconst bossSelectedBuilding = computed<BossBuildingNode | null>(() => {\n  const selected = bossBuildingNodes.value.find(item => item.id === bossSelectedBuildingId.value);\n  return selected ?? bossBuildingNodes.value.find(item => item.状态 === '待验收') ?? bossBuildingNodes.value.find(item => item.状态 === '可扩建') ?? bossBuildingNodes.value[0] ?? null;\n});\n\nconst bossSelectedBuildingProject = computed(() => {\n  if (!bossSelectedBuilding.value) {\n    return null;\n  }\n  return bossState.value.工程.find(project => project.类型 === '建筑' && project.建筑ID === bossSelectedBuilding.value?.id) ?? null;\n});\n\nconst bossSelectedBuildingActionText = computed(() => {\n  const building = bossSelectedBuilding.value;\n  if (!building) {\n    return '选择建筑';\n  }\n  if (building.状态 === '待验收') {\n    return '验收';\n  }\n  if (building.状态 === '已建成') {\n    return building.等级 >= building.maxLevel ? '完成' : '升级';\n  }\n  if (building.状态 === '可扩建') {\n    return '扩建';\n  }\n  return building.状态;\n});\n\nconst bossSelectedBuildingCanAct = computed(() => {\n  const building = bossSelectedBuilding.value;\n  if (!building) {\n    return false;\n  }\n  if (building.状态 === '待验收') {\n    return Boolean(bossSelectedBuildingProject.value);\n  }\n  return building.canStart;\n});\n\nconst bossBuiltBuildingCount = computed(() => bossBuildingItems.value.filter(item => item.状态 === '已建成').length);\n\nconst bossUnlockedInfrastructureItems = computed<BossInfrastructureUnlock[]>(() => getBossUnlockedInfrastructureItems(bossState.value));\n\nconst bossUpcomingInfrastructureItems = computed<BossInfrastructureUnlock[]>(() => getBossUpcomingInfrastructureItems(bossState.value));\n\nconst bossActiveCampaignText = computed(() => bossState.value.宣传活动.map(item => `${item.名称}${item.剩余天数}天`).join('、') || '暂无');\n\nconst bossActiveQualityText = computed(() => bossState.value.品质投入.map(item => `${item.项目}${item.剩余天数}天`).join('、') || '暂无');\n\nconst currentBossShiftValue = computed(() => {\n  if (!bossActiveShift.value) {\n    return '';\n  }\n  const employee = bossState.value.员工.find(item => item.姓名 === bossActiveShift.value?.name);\n  return employee?.排班[bossActiveShift.value.index] ?? '';\n});\n\nconst dialogueSpeakerName = computed(() => {\n  if (activeMode.value === '老板') {\n    return bossSpeakerName.value;\n  }\n  return '未开之花';\n});\n\nconst profileGenderLabel = computed(() => {\n  if (profileGenderKey.value === '自定义') {\n    return profileGenderText.value.trim();\n  }\n  return profileGenderKey.value;\n});\n\nconst currentSceneBg = computed(() => {\n  if (activeMode.value === '老板') {\n    return bossBgUrl;\n  }\n  if (activeMode.value === '游客') {\n    return customerBgUrl;\n  }\n  return waiterBgUrl;\n});\n\nconst playPlaque = computed(() => {\n  if (activeMode.value === '老板') {\n    return { main: String(Math.max(1, Math.round(bossState.value.客流 + bossState.value.店铺评分 * 4))), sub: '今日热度' };\n  }\n  if (activeMode.value === '游客') {\n    return { main: '03', sub: '到店次数' };\n  }\n  return { main: 'B', sub: '当前评级' };\n});\n\nconst playStatusItems = computed(() => {\n  if (activeMode.value === '老板') {\n    return [\n      { label: '资金', text: yuan(bossState.value.资金), icon: 'M5 5h14v14H5zM8 9h8M8 13h8' },\n      { label: '时间', text: bossState.value.时间, icon: 'M12 6v6l4 2M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18Z' },\n      { label: '地点', text: bossState.value.地点, icon: 'M12 3 4 9v11h16V9z' },\n    ];\n  }\n  if (activeMode.value === '游客') {\n    return [\n      { label: '资金', text: '¥3,200', icon: 'M5 5h14v14H5zM8 9h8M8 13h8' },\n      { label: '指名', text: '由梨', icon: 'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM4 21a8 8 0 0 1 16 0' },\n      { label: '预约', text: '香柚汤护理', icon: 'M5 7h14v10H5zM8 10h8' },\n    ];\n  }\n  return [\n    { label: '班次', text: '晚班', icon: 'M5 4h14v16H5zM8 2v4M16 2v4M5 9h14' },\n    { label: '区域', text: '香柚汤池', icon: 'M12 3 4 9v11h16V9z' },\n    { label: '收入', text: '¥1,320', icon: 'M5 5h14v14H5zM8 9h8M8 13h8' },\n  ];\n});\n\nconst playShellText = computed(() => {\n  if (activeMode.value === '老板') {\n    return bossDialogueText.value;\n  }\n  if (activeMode.value === '游客') {\n    return '水汽漫过包间门口，指名、服务、好感和联系人会从这里慢慢展开。';\n  }\n  return '更衣室的灯光安静亮着，班次、接客、收入和评级会从这里慢慢展开。';\n});\n\nconst recentErrorText = computed(() => {\n  const error = [...logEntries.value].reverse().find(entry => entry.level === 'error');\n  return error ? `${error.scope}：${error.message}` : '无';\n});\n\nfunction refreshRuntime() {\n  runtime.value = props.services.save.getRuntime();\n  if (runtime.value.activeMode !== '未选择') {\n    activeMode.value = runtime.value.activeMode;\n    selectedMode.value = runtime.value.activeMode;\n  }\n}\n\nfunction showToast(text: string) {\n  toastText.value = text;\n  window.clearTimeout(toastTimer);\n  toastTimer = window.setTimeout(() => {\n    toastText.value = '';\n  }, 1600);\n}\n\nfunction getBossBuildingPrimaryKey(building: BossBuildingCatalogItem): BossInfrastructureKey {\n  const keys = Object.keys(building.条件) as BossInfrastructureKey[];\n  return keys[0] ?? '占地规模';\n}\n\nfunction getBossBuildingRequirementText(building: BossBuildingCatalogItem): string {\n  const entries = Object.entries(building.条件) as [BossInfrastructureKey, number][];\n  return entries.map(([key, level]) => `${getBossInfrastructureLabel(key)} ${level}级`).join('、') || '无';\n}\n\nfunction getBossBuildingLevelText(building: BossBuildingCatalogItem): string {\n  if (building.状态 === '已建成') {\n    return `等级 ${building.等级}`;\n  }\n  return building.状态;\n}\n\nfunction getBossBuildingStatusClass(status: BossBuildingCatalogItem['状态']): string {\n  if (status === '已建成') {\n    return 'is-built';\n  }\n  if (status === '可扩建') {\n    return 'is-expandable';\n  }\n  if (status === '施工中') {\n    return 'is-building';\n  }\n  if (status === '待验收') {\n    return 'is-accept';\n  }\n  return 'is-locked';\n}\n\nfunction getBossBuildingEffectText(building: BossBuildingCatalogItem): string {\n  if (building.分类 === '经营') {\n    return '建成后主要影响经营稳定、员工恢复、维护压力或预约承接。';\n  }\n  if (building.分类 === '项目') {\n    return '建成后会开放或强化对应消费项目，并进入日结订单计算。';\n  }\n  return '建成后会开放新区域，提高接待空间、舒适度和后续扩建路线。';\n}\n\nfunction makeBossBuildingNodes(buildings: BossBuildingCatalogItem[]): BossBuildingNode[] {\n  const branchCounts = new Map<BossInfrastructureKey, number>();\n  return buildings.map(building => {\n    const primaryKey = getBossBuildingPrimaryKey(building);\n    const branchIndex = Math.max(0, BOSS_BUILDING_BRANCH_ORDER.indexOf(primaryKey));\n    const used = branchCounts.get(primaryKey) ?? 0;\n    branchCounts.set(primaryKey, used + 1);\n    const maxRequirement = Math.max(1, ...(Object.values(building.条件) as number[]));\n    const sameBranchOffset = used % 3;\n    const wrappedRow = Math.floor(used / 3);\n    const x = 42 + maxRequirement * 216 + sameBranchOffset * 58 + (building.分类 === '经营' ? 34 : 0);\n    const y = 42 + branchIndex * 80 + wrappedRow * 28;\n    const statusClass = getBossBuildingStatusClass(building.状态);\n    const actionText = building.状态 === '已建成' ? (building.等级 >= building.maxLevel ? '完成' : '升级') : building.状态 === '可扩建' ? '扩建' : building.状态;\n    return {\n      ...building,\n      x,\n      y,\n      statusClass,\n      levelText: getBossBuildingLevelText(building),\n      requirementText: getBossBuildingRequirementText(building),\n      actionText,\n      canAct: building.canStart,\n      effectText: getBossBuildingEffectText(building),\n    };\n  });\n}\n\nfunction makeBossBuildingLines(nodes: BossBuildingNode[]): BossBuildingLine[] {\n  const nodeMap = new Map(nodes.map(node => [node.id, node]));\n  return nodes\n    .filter(node => !Object.values(BOSS_BUILDING_ANCHORS).includes(node.id))\n    .map(node => {\n      const parentId = BOSS_BUILDING_ANCHORS[getBossBuildingPrimaryKey(node)] ?? 'area_lobby';\n      const parent = nodeMap.get(parentId) ?? nodeMap.get('area_lobby');\n      if (!parent || parent.id === node.id) {\n        return null;\n      }\n      return {\n        id: `${parent.id}-${node.id}`,\n        x1: parent.x + 70,\n        y1: parent.y + 24,\n        x2: node.x,\n        y2: node.y + 24,\n        statusClass: node.statusClass,\n      };\n    })\n    .filter((line): line is BossBuildingLine => Boolean(line));\n}\n\nfunction resetBossBuildingPan() {\n  bossBuildingPan.value = { x: 0, y: 0 };\n}\n\nfunction startBossBuildingPan(event: PointerEvent) {\n  bossBuildingDrag.value = {\n    pointerId: event.pointerId,\n    startX: event.clientX,\n    startY: event.clientY,\n    originX: bossBuildingPan.value.x,\n    originY: bossBuildingPan.value.y,\n  };\n  (event.currentTarget as HTMLElement).setPointerCapture?.(event.pointerId);\n}\n\nfunction moveBossBuildingPan(event: PointerEvent) {\n  const drag = bossBuildingDrag.value;\n  if (!drag || drag.pointerId !== event.pointerId) {\n    return;\n  }\n  bossBuildingPan.value = {\n    x: Math.round(drag.originX + event.clientX - drag.startX),\n    y: Math.round(drag.originY + event.clientY - drag.startY),\n  };\n}\n\nfunction endBossBuildingPan(event: PointerEvent) {\n  if (bossBuildingDrag.value?.pointerId === event.pointerId) {\n    (event.currentTarget as HTMLElement).releasePointerCapture?.(event.pointerId);\n    bossBuildingDrag.value = null;\n  }\n}\n\nfunction yuan(value: number) {\n  return `¥${Math.round(value).toLocaleString('zh-CN')}`;\n}\n\nfunction signedYuan(value: number) {\n  const rounded = Math.round(value);\n  const prefix = rounded > 0 ? '+' : '';\n  return `${prefix}${yuan(rounded)}`;\n}\n\nfunction signedNumber(value: number) {\n  const rounded = Math.round(value);\n  return `${rounded > 0 ? '+' : ''}${rounded}`;\n}\n\nfunction percent(value: number) {\n  return `${Math.round(value * 100)}%`;\n}\n\nfunction setBossLine(name: string, text: string) {\n  bossSpeakerName.value = name;\n  bossDialogueText.value = text;\n}\n\nasync function syncBossMvuSnapshot() {\n  if (activeMode.value !== '老板') {\n    return;\n  }\n  await props.services.mvuRuntime.mergeCurrentStatData(makeBossCommonStatData(bossState.value), '老板');\n}\n\nasync function activateBossMvuBlocks(\n  blockIds: TangquanMvuBlockId[],\n  context: BossMvuBlockContext = {},\n  reason = '更新当前变量块',\n) {\n  if (activeMode.value !== '老板') {\n    return;\n  }\n  const current = await props.services.mvuRuntime.readCurrentStatData();\n  const result = composeStatDataWithBlocks(current, bossState.value, mvuBlockStore.value, blockIds, context);\n  mvuBlockStore.value = result.store;\n  await props.services.mvuRuntime.replaceCurrentStatData(result.statData, '老板', false);\n  props.services.log.info('MVU变量块', '已装入当前变量块', { reason, blockIds, context });\n}\n\nasync function refreshActiveBossMvuBlocks(reason = '刷新当前变量块') {\n  if (activeMode.value !== '老板') {\n    return;\n  }\n  if (mvuBlockStore.value.activeBlockIds.length === 0) {\n    await syncBossMvuSnapshot();\n    return;\n  }\n  await activateBossMvuBlocks(\n    mvuBlockStore.value.activeBlockIds,\n    mvuBlockStore.value.activeContext,\n    reason,\n  );\n}\n\nasync function deactivateBossMvuBlocks(reason = '卸下当前变量块') {\n  if (activeMode.value !== '老板') {\n    return;\n  }\n  const current = await props.services.mvuRuntime.readCurrentStatData();\n  const result = deactivateStatDataBlocks(current, bossState.value, mvuBlockStore.value);\n  mvuBlockStore.value = result.store;\n  await props.services.mvuRuntime.replaceCurrentStatData(result.statData, '老板', false);\n  props.services.log.info('MVU变量块', '已卸下当前变量块', { reason });\n}\n\nasync function saveActiveBossMvuBlocks(reason = '保存当前变量块') {\n  if (activeMode.value !== '老板') {\n    return;\n  }\n  const current = await props.services.mvuRuntime.readCurrentStatData();\n  mvuBlockStore.value = saveActiveBlocksFromStatData(mvuBlockStore.value, current);\n  props.services.log.info('MVU变量块', '已保存当前变量块', {\n    reason,\n    activeBlockIds: mvuBlockStore.value.activeBlockIds,\n  });\n}\n\nasync function replaceTemporaryEntries(entryIds: string[], reason: string, contentMap: Record<string, string> = {}) {\n  const nextIds = _.uniq(entryIds);\n  const oldIds = activeTemporaryEntryIds.value;\n  const disableIds = oldIds.filter(id => !nextIds.includes(id));\n  if (disableIds.length > 0) {\n    await props.services.worldbookRuntime.disableEntries(disableIds, reason);\n  }\n  if (nextIds.length > 0) {\n    await props.services.worldbookRuntime.enableEntries(nextIds, reason, contentMap);\n  }\n  activeTemporaryEntryIds.value = nextIds;\n}\n\nasync function openAirpScene(scene: AirpSceneState) {\n  await runAction('进入现场', async () => {\n    await replaceTemporaryEntries(scene.entryIds, scene.title, scene.entryContentMap);\n    if (scene.mode === '老板') {\n      await activateBossMvuBlocks(scene.blockIds ?? [], scene.blockContext ?? {}, scene.title);\n    }\n    await props.services.mvuRuntime.setInteractionScene(scene.scene, scene.mode);\n    airpState.value = scene;\n    airpInput.value = '';\n    if (scene.mode === '老板') {\n      setBossLine(scene.speaker, scene.line);\n      closeBossMenu();\n    }\n    showToast('现场已准备');\n  });\n}\n\nasync function closeAirpScene() {\n  const scene = airpState.value;\n  if (!scene) {\n    return;\n  }\n  await runAction('离开现场', async () => {\n    if (scene.mode === '老板') {\n      await deactivateBossMvuBlocks('离开现场');\n    } else {\n      await props.services.mvuRuntime.clearInteractionScene(scene.mode);\n    }\n    await replaceTemporaryEntries([], '离开现场');\n    airpState.value = null;\n    airpInput.value = '';\n    if (scene.mode === '老板') {\n      setBossLine('未开之花', '你暂时离开现场，经营页面会保留刚才的位置。');\n    }\n    showToast('已离开现场');\n  });\n}\n\nfunction getGenerationText(result: string | GenerateToolCallResult): string {\n  if (typeof result === 'string') {\n    return result;\n  }\n  throw new Error('本次生成返回了工具调用结果，暂时不能写入楼层');\n}\n\nasync function readLatestMvuData(): Promise<Mvu.MvuData> {\n  await waitGlobalInitialized('Mvu');\n  return _.cloneDeep(Mvu.getMvuData({ type: 'message', message_id: 'latest' }) ?? {}) as Mvu.MvuData;\n}\n\nasync function submitAirpInput() {\n  const scene = airpState.value;\n  const userText = airpInput.value.trim();\n  if (!scene) {\n    showToast('还没有进入现场');\n    return;\n  }\n  if (!userText) {\n    showToast('先输入要做的事');\n    return;\n  }\n  if (airpSubmitting.value) {\n    return;\n  }\n\n  airpSubmitting.value = true;\n  try {\n    await runAction('现场互动', async () => {\n      await replaceTemporaryEntries(scene.entryIds, scene.title, scene.entryContentMap);\n      const oldMvuData = await readLatestMvuData();\n      const result = await generate({\n        user_input: userText,\n        should_stream: true,\n      });\n      const message = getGenerationText(result);\n      const newMvuData = await Mvu.parseMessage(message, oldMvuData);\n      await createChatMessages(\n        [\n          { role: 'user', message: userText, data: oldMvuData },\n          { role: 'assistant', message, data: newMvuData },\n        ],\n        { insert_before: 'end', refresh: 'all' },\n      );\n      await props.services.zeroLock.mirrorNow('现场互动完成');\n      props.services.beautifier.applyNow('现场互动完成');\n      if (scene.mode === '老板') {\n        await saveActiveBossMvuBlocks('现场互动完成');\n      }\n      airpInput.value = '';\n      if (scene.mode === '老板') {\n        setBossLine(scene.speaker, '现场已经继续，最新内容会显示在下一楼。');\n      }\n      showToast('已生成');\n    });\n  } finally {\n    airpSubmitting.value = false;\n  }\n}\n\nfunction isRecord(value: unknown): value is Record<string, unknown> {\n  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);\n}\n\nfunction extractSavedBossState(data: Record<string, unknown>): BossPageState | null {\n  const frontendData = data['前端数据'];\n  if (!isRecord(frontendData)) {\n    return null;\n  }\n  return normalizeBossPageState(frontendData['老板页面']);\n}\n\nfunction extractSavedMvuBlockStore(data: Record<string, unknown>): TangquanMvuBlockStore {\n  const frontendData = data['前端数据'];\n  if (!isRecord(frontendData)) {\n    return makeMvuBlockStore();\n  }\n  return normalizeMvuBlockStore(frontendData['变量块仓库']);\n}\n\nfunction resetBossPageState(\n  nextState: BossPageState = makeBossPageState(),\n  nextMvuBlockStore: TangquanMvuBlockStore = makeMvuBlockStore(),\n) {\n  bossState.value = recalculateBossState(nextState);\n  mvuBlockStore.value = cloneMvuBlockStore(nextMvuBlockStore);\n  bossView.value = 'overview';\n  bossMenuOpen.value = false;\n  bossActiveShift.value = null;\n  airpState.value = null;\n  airpInput.value = '';\n  activeTemporaryEntryIds.value = [];\n  setBossLine('未开之花', '店铺已经开灯，今天的经营、排班、现场互动会从这里继续。');\n}\n\nfunction makeCurrentSaveDataPatch(): Record<string, unknown> {\n  if (activeMode.value !== '老板') {\n    return {};\n  }\n  return {\n    前端数据: {\n      老板页面: cloneBossPageState(bossState.value),\n      变量块仓库: cloneMvuBlockStore(mvuBlockStore.value),\n    },\n  };\n}\n\nasync function runBossMutation(\n  label: string,\n  mutate: () => { ok: boolean; message: string; state: BossPageState },\n  onSuccess?: () => void | Promise<void>,\n) {\n  await runAction(label, async () => {\n    const result = mutate();\n    if (!result.ok) {\n      showToast(result.message);\n      return;\n    }\n    bossState.value = result.state;\n    await refreshActiveBossMvuBlocks(label);\n    await onSuccess?.();\n    showToast(result.message);\n  });\n}\n\nfunction openBossMenu(view: BossMenuView = bossView.value) {\n  bossView.value = view;\n  bossMenuOpen.value = true;\n}\n\nfunction closeBossMenu() {\n  bossMenuOpen.value = false;\n}\n\nfunction findBossEmployee(name: string): BossEmployee | null {\n  return bossState.value.员工.find(employee => employee.姓名 === name) ?? null;\n}\n\nfunction findBossArea(name: string) {\n  return bossState.value.区域.find(area => area.名称 === name) ?? null;\n}\n\nfunction findBossProjectByArea(name: string) {\n  return bossState.value.项目.find(project => project.名称 === name || project.设施需求 === name) ?? null;\n}\n\nfunction getBossBuiltLevel(buildingId: string): number {\n  return bossState.value.建筑.find(building => building.id === buildingId)?.等级 ?? 0;\n}\n\nfunction resolveBossBuildingNameForArea(areaName: string): string {\n  return TANGQUAN_AREA_TO_BUILDING[areaName] ?? areaName;\n}\n\nfunction findBossBuildingByName(name: string): BossBuildingCatalogItem | null {\n  const buildingName = resolveBossBuildingNameForArea(name);\n  return getBossBuildingCatalog(bossState.value).find(building => building.名称 === buildingName) ?? null;\n}\n\nfunction makeBossInfrastructureWorldbookEntryIds(requirements: Partial<Record<BossInfrastructureKey, number>>) {\n  return (Object.keys(requirements) as BossInfrastructureKey[])\n    .map(key => {\n      const currentLevel = bossState.value.基建[key];\n      return currentLevel > 0 ? makeTangquanInfrastructureEntryId(key, currentLevel) : '';\n    })\n    .filter(Boolean);\n}\n\nfunction makeBossBuildingWorldbookEntryIds(building: BossBuildingCatalogItem | null): string[] {\n  if (!building) {\n    return [];\n  }\n  const builtLevel = getBossBuiltLevel(building.id);\n  const ids = makeBossInfrastructureWorldbookEntryIds(building.条件);\n  if (builtLevel > 0) {\n    ids.push(makeTangquanBuildingEntryId(building.名称, builtLevel));\n  }\n  return _.uniq(ids);\n}\n\nfunction makeBossAreaWorldbookEntryIds(areaName: string): string[] {\n  const building = findBossBuildingByName(areaName);\n  if (building) {\n    return makeBossBuildingWorldbookEntryIds(building);\n  }\n  const infrastructureName = areaName as BossInfrastructureKey;\n  if (Object.prototype.hasOwnProperty.call(bossState.value.基建, infrastructureName)) {\n    return makeBossInfrastructureWorldbookEntryIds({ [infrastructureName]: bossState.value.基建[infrastructureName] });\n  }\n  return [];\n}\n\nfunction makeBossProjectWorldbookEntryIds(project: BossProject | null): string[] {\n  if (!project) {\n    return [];\n  }\n  const buildingName = TANGQUAN_PROJECT_TO_BUILDING[project.名称];\n  const buildingIds = buildingName ? makeBossBuildingWorldbookEntryIds(findBossBuildingByName(buildingName)) : [];\n  return _.uniq([makeTangquanProjectEntryId(project.名称), ...buildingIds]);\n}\n\nfunction makeBossAreaEntryContentMap(areaName: string): Record<string, string> {\n  const area = findBossArea(areaName);\n  return area ? { 'area.current': makeAreaEntryContent(area) } : {};\n}\n\nfunction makeBossEmployeeEntryContentMap(employee: BossEmployee): Record<string, string> {\n  return {\n    ...makeBossAreaEntryContentMap(employee.区域),\n    'character.current-employee': makeEmployeeEntryContent(employee),\n  };\n}\n\nfunction makeBossServiceEntryContentMap(employee: BossEmployee, nomination?: BossPageState['指名'][number]): Record<string, string> {\n  const contentMap = makeBossEmployeeEntryContentMap(employee);\n  if (nomination) {\n    contentMap['character.current-guest'] = makeGuestEntryContent(nomination);\n    const project = findBossProjectByArea(nomination.区域);\n    if (project) {\n      contentMap['project.current'] = makeProjectEntryContent(project);\n    }\n  }\n  return contentMap;\n}\n\nfunction isBossShiftSelected(name: string, index: number) {\n  return bossActiveShift.value?.name === name && bossActiveShift.value.index === index;\n}\n\nfunction selectBossShift(name: string, index: number) {\n  bossActiveShift.value = { name, index };\n}\n\nfunction setBossShiftOption(choice: string) {\n  if (!bossActiveShift.value) {\n    return;\n  }\n  const employee = findBossEmployee(bossActiveShift.value.name);\n  if (!employee) {\n    return;\n  }\n  employee.排班[bossActiveShift.value.index] = choice;\n}\n\nasync function confirmBossSchedule() {\n  await runAction('确认排班', async () => {\n    bossState.value = confirmBossScheduleState(bossState.value);\n    await refreshActiveBossMvuBlocks('确认排班');\n    showToast('排班已确认');\n    setBossLine('由梨', '“排班已经确认，我会按新的安排去准备。”');\n  });\n}\n\nasync function goBossArea(areaName: string) {\n  await runAction('前往区域', async () => {\n    bossState.value.地点 = areaName;\n    await replaceTemporaryEntries([], '前往区域');\n    await activateBossMvuBlocks(['boss.area'], { areaName }, '前往区域');\n    await props.services.mvuRuntime.clearInteractionScene('老板');\n    setBossLine(bossCurrentStaff.value[0]?.姓名 || '店员', `“这里是${areaName}，当前客流已经更新在菜单里。”`);\n  });\n}\n\nasync function goBossEmployee(name: string) {\n  const employee = findBossEmployee(name);\n  if (!employee) {\n    return;\n  }\n  await runAction('前往员工所在区域', async () => {\n    bossState.value.地点 = employee.区域;\n    await replaceTemporaryEntries([], '前往员工所在区域');\n    await activateBossMvuBlocks(['boss.area', 'boss.employee'], {\n      areaName: employee.区域,\n      employeeName: employee.姓名,\n    }, '前往员工所在区域');\n    await props.services.mvuRuntime.clearInteractionScene('老板');\n    setBossLine(employee.姓名, `“老板，您过来了。现在这里是${employee.区域}。”`);\n  });\n}\n\nasync function talkBossEmployee(name: string) {\n  const employee = findBossEmployee(name);\n  if (!employee) {\n    showToast('没有找到这名员工');\n    return;\n  }\n  await openAirpScene({\n    mode: '老板',\n    title: `与${employee.姓名}交谈`,\n    note: `${employee.区域} · 日薪 ${yuan(employee.日薪)} · 满意 ${employee.满意度}`,\n    speaker: employee.姓名,\n    line: '“我现在方便说话，您想先问今天的客人，还是问排班？”',\n    placeholder: '输入你要对员工说的话，或你想询问、安排的内容。',\n    entryIds: ['area.current', 'character.current-employee', ...makeBossAreaWorldbookEntryIds(employee.区域)],\n    entryContentMap: makeBossEmployeeEntryContentMap(employee),\n    blockIds: ['boss.overview', 'boss.area', 'boss.employee'],\n    blockContext: {\n      areaName: employee.区域,\n      employeeName: employee.姓名,\n    },\n    scene: {\n      地点: employee.区域,\n      员工: {\n        [employee.姓名]: {\n          日薪: employee.日薪,\n          当前安排: employee.区域,\n          评级: employee.评级,\n          评分: employee.评分,\n          满意度: employee.满意度,\n          疲劳: employee.疲劳,\n        },\n      },\n    },\n  });\n}\n\nasync function raiseBossSalary(name: string) {\n  await runBossMutation('加日薪', () => raiseBossEmployeeSalary(bossState.value, name));\n}\n\nasync function checkBossService(name: string) {\n  const employee = findBossEmployee(name);\n  if (!employee) {\n    return;\n  }\n  bossState.value.地点 = employee.区域;\n  const nomination = bossState.value.指名.find(item => item.员工 === employee.姓名 && item.剩余天数 > 0);\n  const scene: Record<string, unknown> = {\n    地点: employee.区域,\n    员工: {\n      [employee.姓名]: {\n        当前状态: employee.状态,\n        日薪: employee.日薪,\n        当前安排: employee.区域,\n        服务次数: employee.服务次数,\n        指名次数: employee.指名次数,\n        额外结果次数: employee.额外结果次数,\n      },\n    },\n  };\n  if (nomination) {\n    scene.指名关系 = {\n      [employee.姓名]: {\n        客人: nomination.客人,\n        指名剩余天数: nomination.剩余天数,\n        当前项目: nomination.区域,\n        员工个人收入预估: nomination.预计收入,\n      },\n    };\n  }\n  const project = nomination ? findBossProjectByArea(nomination.区域) : null;\n  const entryIds = ['area.current', 'character.current-employee', ...makeBossAreaWorldbookEntryIds(employee.区域)];\n  if (nomination) {\n    entryIds.push('character.current-guest');\n  }\n  if (project) {\n    entryIds.push('project.current', ...makeBossProjectWorldbookEntryIds(project));\n  }\n  await openAirpScene({\n    mode: '老板',\n    title: `查看${employee.姓名}的服务`,\n    note: nomination ? `${nomination.客人} · 指名剩余${nomination.剩余天数}天` : `${employee.区域} · 当前服务`,\n    speaker: employee.姓名,\n    line: '“我会继续照看这边。您要亲自观察的话，可以从这里开始。”',\n    placeholder: '输入你进入现场后要做什么，例如观察、询问客人、提醒员工或亲自介入。',\n    entryIds,\n    entryContentMap: makeBossServiceEntryContentMap(employee, nomination),\n    blockIds: nomination\n      ? ['boss.area', 'boss.employee', 'boss.guest', 'boss.service']\n      : ['boss.area', 'boss.employee', 'boss.service'],\n    blockContext: {\n      areaName: employee.区域,\n      employeeName: employee.姓名,\n    },\n    scene,\n  });\n}\n\nasync function adjustBossProject(name: string, direction: 'up' | 'down') {\n  const label = direction === 'up' ? '涨价' : '降价';\n  await runBossMutation(`${label}项目`, () => adjustBossProjectPrice(bossState.value, name, direction));\n}\n\nasync function investBossQuality(name: string) {\n  if (!(await confirmAction(`确定为 ${name} 投入更好的材料和准备吗？这会提高短期体验和点单意愿。`, '品质投入'))) {\n    return;\n  }\n  await runBossMutation('品质投入', () => investBossProjectQuality(bossState.value, name));\n}\n\nasync function talkBossMarket(name: string) {\n  const candidate = bossState.value.人才市场.find(item => item.姓名 === name);\n  if (!candidate) {\n    showToast('没有找到这名候选');\n    return;\n  }\n  bossState.value.地点 = '办公室';\n  const officeContentMap = makeBossAreaEntryContentMap('办公室');\n  const officeEntryIds = Object.keys(officeContentMap).length > 0 ? ['area.current', ...makeBossAreaWorldbookEntryIds('办公室')] : makeBossAreaWorldbookEntryIds('办公室');\n  await openAirpScene({\n    mode: '老板',\n    title: `与${candidate.姓名}交流`,\n    note: `${candidate.类型} · 市场价格 ${yuan(candidate.市场价格)}`,\n    speaker: candidate.姓名,\n    line: '“如果您想了解我，可以直接问。”',\n    placeholder: '输入你要交流的问题、条件或试探。',\n    entryIds: [...officeEntryIds, 'character.current-candidate'],\n    entryContentMap: {\n      ...officeContentMap,\n      'character.current-candidate': makeCandidateEntryContent(candidate, '人才市场'),\n    },\n    blockIds: ['boss.candidate'],\n    blockContext: {\n      candidateName: candidate.姓名,\n    },\n    scene: {\n      地点: '办公室',\n      候选人: {\n        [candidate.姓名]: {\n          来源: '人才市场',\n          期望日薪: candidate.期望日薪,\n          评级: candidate.评级,\n          市场价格: candidate.市场价格,\n          简介: candidate.说明,\n        },\n      },\n    },\n  });\n}\n\nasync function buyBossMarket(name: string) {\n  const candidate = bossState.value.人才市场.find(item => item.姓名 === name);\n  if (!candidate) {\n    showToast('没有找到这名候选');\n    return;\n  }\n  if (!(await confirmAction(`确定花费 ${yuan(candidate.市场价格)} 邀请 ${candidate.姓名} 加入名册吗？`, '人才市场'))) {\n    return;\n  }\n  await runBossMutation('买入人才', () => buyBossMarketCandidate(bossState.value, name), async () => {\n    await deactivateBossMvuBlocks('买入人才');\n    await replaceTemporaryEntries([], '买入人才');\n  });\n}\n\nasync function talkBossRecruit() {\n  const recruit = bossState.value.招聘;\n  bossState.value.地点 = '办公室';\n  const officeContentMap = makeBossAreaEntryContentMap('办公室');\n  const officeEntryIds = Object.keys(officeContentMap).length > 0 ? ['area.current', ...makeBossAreaWorldbookEntryIds('办公室')] : makeBossAreaWorldbookEntryIds('办公室');\n  await openAirpScene({\n    mode: '老板',\n    title: `面试${recruit.姓名}`,\n    note: `期望日薪 ${yuan(recruit.期望日薪)} · 拒绝记录 ${recruit.拒绝记录}`,\n    speaker: recruit.姓名,\n    line: '“我准备好了，您想先问什么？”',\n    placeholder: '输入面试问题、岗位说明、待遇条件或观察要求。',\n    entryIds: [...officeEntryIds, 'character.current-candidate'],\n    entryContentMap: {\n      ...officeContentMap,\n      'character.current-candidate': makeCandidateEntryContent(recruit, '招聘'),\n    },\n    blockIds: ['boss.candidate'],\n    blockContext: {\n      recruit: true,\n    },\n    scene: {\n      地点: '办公室',\n      候选人: {\n        [recruit.姓名]: {\n          来源: '招聘候选',\n          期望日薪: recruit.期望日薪,\n          拒绝记录: recruit.拒绝记录,\n          简介: recruit.说明,\n        },\n      },\n    },\n  });\n}\n\nasync function hireBossRecruit() {\n  const recruit = bossState.value.招聘;\n  if (!(await confirmAction(`确定录用 ${recruit.姓名} 吗？入职准备会扣除一笔费用。`, '录用候选'))) {\n    return;\n  }\n  await runBossMutation('录用候选', () => hireBossRecruitCandidate(bossState.value), async () => {\n    await deactivateBossMvuBlocks('录用候选');\n    await replaceTemporaryEntries([], '录用候选');\n  });\n}\n\nasync function rejectBossRecruit() {\n  await runAction('拒绝候选', async () => {\n    bossState.value = rejectBossRecruitCandidate(bossState.value);\n    await deactivateBossMvuBlocks('拒绝候选');\n    await replaceTemporaryEntries([], '拒绝候选');\n    showToast('已拒绝，候选回到人才库');\n  });\n}\n\nasync function upgradeBossFacility(key: BossInfrastructureKey) {\n  const cost = getBossInfrastructureUpgradeCost(bossState.value, key);\n  const item = bossInfrastructureItems.value.find(entry => entry.key === key);\n  if (!item || item.isMaxed) {\n    showToast('这条建设路线已经完成');\n    return;\n  }\n  const unlockText = item.nextUnlocks.length ? `，可能开放 ${item.nextUnlocks.map(unlock => unlock.名称).join('、')}` : '';\n  if (!(await confirmAction(`确定启动 ${item.label} ${item.level}→${item.level + 1} 的工程吗？总费用约 ${yuan(cost)}，预计 ${item.days} 天${unlockText}。`, '扩建设施'))) {\n    return;\n  }\n  await runBossMutation('扩建设施', () => upgradeBossInfrastructure(bossState.value, key));\n}\n\nasync function startBossBuilding(buildingId: string) {\n  const building = bossBuildingItems.value.find(item => item.id === buildingId);\n  if (!building) {\n    showToast('没有找到这项建筑');\n    return;\n  }\n  const action = building.状态 === '已建成' ? '升级' : '扩建';\n  if (!(await confirmAction(`确定${action}${building.名称}吗？预计花费 ${yuan(building.cost)}，工期 ${building.days} 天。`, `${action}建筑`))) {\n    return;\n  }\n  await runBossMutation(`${action}建筑`, () => startBossBuildingProject(bossState.value, buildingId));\n}\n\nasync function handleBossSelectedBuildingAction() {\n  const building = bossSelectedBuilding.value;\n  if (!building) {\n    showToast('先选择一项建筑');\n    return;\n  }\n  if (building.状态 === '待验收') {\n    const project = bossSelectedBuildingProject.value;\n    if (!project) {\n      showToast('没有找到待验收工程');\n      return;\n    }\n    await acceptBossProject(project.id);\n    return;\n  }\n  await startBossBuilding(building.id);\n}\n\nasync function acceptBossProject(projectId: string) {\n  if (!(await confirmAction('确定验收这项工程吗？验收后设施等级正式生效。', '工程验收'))) {\n    return;\n  }\n  await runBossMutation('工程验收', () => acceptBossConstructionProject(bossState.value, projectId));\n}\n\nasync function maintainBossFacilities() {\n  const cost = bossMaintenanceCost.value;\n  if (cost <= 0) {\n    showToast('当前维护度已经很高');\n    return;\n  }\n  if (!(await confirmAction(`确定花费 ${yuan(cost)} 进行维护吗？`, '环境维护'))) {\n    return;\n  }\n  await runBossMutation('环境维护', () => maintainBossInfrastructure(bossState.value));\n}\n\nasync function startBossCampaign() {\n  if (!(await confirmAction('确定开始宣传活动吗？宣传会花钱，并在数日内提高客流和项目热度。', '宣传活动'))) {\n    return;\n  }\n  await runBossMutation('宣传活动', () => startBossMarketingCampaign(bossState.value));\n}\n\nasync function investBossCare() {\n  if (!(await confirmAction('确定安排员工福利吗？这会花钱，提高满意度并降低疲劳和离职风险。', '员工福利'))) {\n    return;\n  }\n  await runBossMutation('员工福利', () => investBossStaffCare(bossState.value));\n}\n\nasync function toggleBossPause() {\n  if (bossState.value.营业状态 === '暂停营业') {\n    await runBossMutation('恢复营业', () => resumeBossBusiness(bossState.value), () => {\n      setBossLine('未开之花', '店铺重新开始接待客人。');\n    });\n    return;\n  }\n  if (!(await confirmAction('确定暂停营业吗？暂停后今日不会继续增加新客，但仍可处理店内事务。', '暂停营业'))) {\n    return;\n  }\n  await runBossMutation('暂停营业', () => pauseBossBusiness(bossState.value), () => {\n    setBossLine('未开之花', '店铺已经暂停接客，可以先处理排班、员工或现场事务。');\n  });\n}\n\nasync function closeBossToday() {\n  if (!(await confirmAction('确定今日停业吗？停业后今日客流归零，结算时没有营业收入，但仍会产生基础支出。', '今日停业'))) {\n    return;\n  }\n  await runBossMutation('今日停业', () => closeBossBusinessToday(bossState.value), () => {\n    openBossMenu('settlement');\n    setBossLine('未开之花', '今日已经停业，账本会按无客流的一天处理。');\n  });\n}\n\nasync function restBossToday() {\n  if (!(await confirmAction('确定休息一天吗？这会直接推进到次日 00:00，并扣除最低维护和留守成本。', '休息一天'))) {\n    return;\n  }\n  await runBossMutation('休息一天', () => restBossOneDay(bossState.value), async () => {\n    openBossMenu('settlement');\n    await activateBossMvuBlocks(['boss.settlement'], { settlement: true }, '休息一天');\n    setBossLine('未开之花', '店里安静休整了一天，员工状态稍微恢复。');\n  });\n}\n\nasync function closeBossDay() {\n  if (bossState.value.今日已结算) {\n    openBossMenu('settlement');\n    showToast('今日已经结算过了');\n    return;\n  }\n  if (!(await confirmAction('确定进行今日结算吗？结算后时间推进到 00:00。', '今日结算'))) {\n    return;\n  }\n  await runBossMutation('今日结算', () => settleBossDay(bossState.value), async () => {\n    openBossMenu('settlement');\n    await activateBossMvuBlocks(['boss.settlement'], { settlement: true }, '今日结算');\n    setBossLine('未开之花', '今日账本已经封存，明日的客流和员工状态也已刷新。');\n  });\n}\n\nasync function runAction(label: string, action: () => Promise<void>) {\n  if (busy.value) {\n    return;\n  }\n  busy.value = true;\n  props.services.log.info('Vue前端', `${label}开始`);\n  try {\n    await action();\n    props.services.log.info('Vue前端', `${label}完成`);\n  } catch (error) {\n    props.services.log.error('Vue前端', `${label}失败`, String(error));\n    showToast(`${label}失败`);\n  } finally {\n    refreshRuntime();\n    refreshLogs();\n    busy.value = false;\n  }\n}\n\nasync function handleTitleMenu(key: TitleMenuKey) {\n  if (key === 'start') {\n    openModesPanel();\n    return;\n  }\n  if (key === 'continue') {\n    await continueGame();\n    return;\n  }\n  if (key === 'load') {\n    await openLoadPanel();\n    return;\n  }\n  if (key === 'settings') {\n    openSettingsPanel();\n    return;\n  }\n  if (key === 'logs') {\n    activePanel.value = 'logs';\n    refreshLogs();\n    return;\n  }\n}\n\nfunction openModesPanel() {\n  activePage.value = 'home';\n  activePanel.value = 'modes';\n}\n\nasync function openLoadPanel(context: SavePanelContext = 'title') {\n  activePage.value = 'home';\n  savePanelContext.value = context;\n  await loadSlots();\n}\n\nfunction returnToPlay() {\n  if (runtime.value.activeMode === '未选择') {\n    showToast('还没有正在游玩的存档');\n    activePanel.value = 'landing';\n    return;\n  }\n  activePage.value = 'play';\n  activePanel.value = 'landing';\n}\n\nasync function returnToTitle() {\n  if (activePage.value === 'play' && activeMode.value === '老板') {\n    await runAction('返回标题', async () => {\n      await deactivateBossMvuBlocks('返回标题');\n      await replaceTemporaryEntries([], '返回标题');\n      airpState.value = null;\n      airpInput.value = '';\n      activePage.value = 'home';\n      activePanel.value = 'landing';\n      savePanelContext.value = 'title';\n    });\n    return;\n  }\n  activePage.value = 'home';\n  activePanel.value = 'landing';\n  savePanelContext.value = 'title';\n}\n\nfunction openSettingsPanel() {\n  activePage.value = 'home';\n  activePanel.value = 'settings';\n}\n\nasync function loadSlots() {\n  await runAction('查看存档', async () => {\n    slots.value = await props.services.save.listSlots();\n    inspection.value = null;\n    showSaveTools.value = false;\n    activePanel.value = 'load';\n    const fixedSlotCount = slots.value.filter(slot => SAVE_SLOT_IDS.includes(slot.slotId)).length;\n    showToast(fixedSlotCount > 0 ? `找到 ${fixedSlotCount} 份存档` : '暂无存档');\n  });\n}\n\nfunction openProfilePanel() {\n  activePage.value = 'home';\n  activePanel.value = 'profile';\n  inspection.value = null;\n}\n\nfunction makeUserProfileInput(): TangquanUserProfileInput | null {\n  const name = profileName.value.trim();\n  if (!name) {\n    showToast('请填写姓名');\n    return null;\n  }\n  if (!profileGenderLabel.value) {\n    showToast('请填写性别');\n    return null;\n  }\n  return {\n    name,\n    genderKey: profileGenderKey.value,\n    genderText: profileGenderText.value.trim(),\n    description: profileDescription.value.trim(),\n  };\n}\n\nfunction selectedSlotTitle(): string {\n  return selectedSlotMeta.value?.label || slotViews.value.find(slot => slot.id === selectedSlotId.value)?.label || selectedSlotId.value;\n}\n\nfunction confirmAction(message: string, title = '确认操作'): Promise<boolean> {\n  if (pendingConfirmResolve) {\n    return Promise.resolve(false);\n  }\n\n  confirmState.value = { title, message };\n  return new Promise(resolve => {\n    pendingConfirmResolve = resolve;\n  });\n}\n\nfunction resolveConfirm(value: boolean) {\n  const resolve = pendingConfirmResolve;\n  pendingConfirmResolve = null;\n  confirmState.value = null;\n  resolve?.(value);\n}\n\nasync function startGame() {\n  if (activePanel.value !== 'profile') {\n    openProfilePanel();\n    showToast('先填写你的信息');\n    return;\n  }\n\n  const userProfile = makeUserProfileInput();\n  if (!userProfile) {\n    return;\n  }\n\n  if (\n    !(await confirmAction(\n      selectedSlotMeta.value\n        ? `确定覆盖“${selectedSlotTitle()}”并开始新游戏吗？原存档会被替换，当前内容若未保存也不会另行保存。`\n        : `确定在“${selectedSlotTitle()}”开始新游戏吗？当前内容若未保存，不会另行保存。`,\n      '开始游戏',\n    ))\n  ) {\n    return;\n  }\n\n  await runAction('开始游戏', async () => {\n    if (runtime.value.activeMode === '老板') {\n      await deactivateBossMvuBlocks('开始新存档');\n      await replaceTemporaryEntries([], '开始新存档');\n    }\n    const mode = selectedMode.value;\n    const userInfo = {\n      姓名: userProfile.name,\n      性别: profileGenderLabel.value,\n      性别选项: userProfile.genderKey,\n      自设: userProfile.description,\n    };\n    const initialSaveData = props.services.runtime.makeInitialSaveData(mode, userInfo);\n    if (mode === '老板') {\n      _.set(initialSaveData, '前端数据.变量块仓库', makeMvuBlockStore());\n    }\n    const meta = await props.services.save.startSlot(\n      selectedSlotId.value,\n      mode,\n      `${mode}存档`,\n      initialSaveData,\n      userProfile,\n    );\n    await props.services.runtime.prepareNewGame(mode, selectedSlotId.value);\n    await refreshSlotsQuietly();\n    activeMode.value = mode;\n    if (mode === '老板') {\n      const savedBossState = extractSavedBossState(initialSaveData);\n      resetBossPageState(savedBossState ?? makeBossPageState(), extractSavedMvuBlockStore(initialSaveData));\n      await syncBossMvuSnapshot();\n    }\n    currentSlotLabel.value = meta.label;\n    activePage.value = 'play';\n    showToast('已开始');\n  });\n}\n\nasync function loadSlot(slotId: string) {\n  await runAction('载入存档', async () => {\n    if (runtime.value.activeMode === '老板') {\n      await deactivateBossMvuBlocks('载入存档');\n      await replaceTemporaryEntries([], '载入存档');\n    }\n    const loaded = await props.services.save.loadSlot(slotId);\n    if (loaded.meta.mode !== '未选择') {\n      activeMode.value = loaded.meta.mode;\n      selectedMode.value = loaded.meta.mode;\n      await props.services.runtime.activateLoadedMode(loaded.meta.mode, loaded.meta.slotId);\n      if (loaded.meta.mode === '老板') {\n        resetBossPageState(\n          extractSavedBossState(loaded.payload.data) ?? makeBossPageState(),\n          extractSavedMvuBlockStore(loaded.payload.data),\n        );\n        await refreshActiveBossMvuBlocks('载入存档');\n      }\n    }\n    currentSlotLabel.value = loaded.meta.label;\n    activePage.value = 'play';\n    showToast('已载入');\n  });\n}\n\nasync function loadSelectedSlot() {\n  if (!selectedSlotMeta.value) {\n    showToast('这份存档尚未开始');\n    return;\n  }\n  if (!(await confirmAction(`确定载入“${selectedSlotTitle()}”吗？当前聊天会切换到这份存档；当前内容若未保存，不会另行保存。`, '载入存档'))) {\n    return;\n  }\n  await loadSlot(selectedSlotId.value);\n}\n\nasync function saveSelectedSlot() {\n  if (!(await confirmAction(`确定把当前游玩进度保存到“${selectedSlotTitle()}”吗？`, '保存存档'))) {\n    return;\n  }\n  await runAction('保存存档', async () => {\n    await saveActiveBossMvuBlocks('保存存档');\n    const meta = await props.services.save.saveCurrentAsSlot(\n      selectedSlotId.value,\n      selectedSlotMeta.value?.label,\n      makeCurrentSaveDataPatch(),\n    );\n    await refreshSlotsQuietly();\n    currentSlotLabel.value = meta.label;\n    inspection.value = null;\n    showToast('已保存');\n  });\n}\n\nasync function deleteSelectedSlot() {\n  if (!selectedSlotMeta.value) {\n    showToast('这份存档尚未开始');\n    return;\n  }\n  if (!(await confirmAction(`确定删除“${selectedSlotTitle()}”吗？删除后不可直接恢复。`, '删除存档'))) {\n    return;\n  }\n  await runAction('删除存档', async () => {\n    await props.services.save.deleteSlot(selectedSlotId.value);\n    await refreshSlotsQuietly();\n    inspection.value = null;\n    showToast('已删除');\n  });\n}\n\nasync function inspectSelectedSlot() {\n  if (!selectedSlotMeta.value) {\n    showToast('这份存档尚未开始');\n    return;\n  }\n  if (!(await confirmAction(`确定检查“${selectedSlotTitle()}”吗？检查期间请不要操作页面。`, '检查存档'))) {\n    return;\n  }\n  await runAction('检查存档', async () => {\n    inspection.value = await props.services.save.inspectSlot(selectedSlotId.value);\n    showToast(inspection.value.ok ? '检查通过' : '发现异常');\n  });\n}\n\nasync function repairSelectedSlot() {\n  if (!selectedSlotMeta.value) {\n    showToast('这份存档尚未开始');\n    return;\n  }\n  if (!(await confirmAction(`确定修复“${selectedSlotTitle()}”吗？修复会重写这份存档的索引信息。`, '修复存档'))) {\n    return;\n  }\n  await runAction('修复存档', async () => {\n    await props.services.save.repairSlot(selectedSlotId.value);\n    await refreshSlotsQuietly();\n    inspection.value = await props.services.save.inspectSlot(selectedSlotId.value);\n    showToast(inspection.value.ok ? '已修复' : '已尝试修复');\n  });\n}\n\nasync function exportSelectedSlot() {\n  if (!selectedSlotMeta.value) {\n    showToast('这份存档尚未开始');\n    return;\n  }\n  if (!(await confirmAction(`确定导出“${selectedSlotTitle()}”吗？`, '导出存档'))) {\n    return;\n  }\n  await runAction('导出存档', async () => {\n    const exported = await props.services.save.exportSlot(selectedSlotId.value);\n    downloadText(exported.filename, exported.content, exported.mime);\n    showToast('已导出');\n  });\n}\n\nfunction chooseImportFile() {\n  importInput.value?.click();\n}\n\nasync function handleImportFile(event: Event) {\n  const input = event.target as HTMLInputElement;\n  const file = input.files?.[0] ?? null;\n  input.value = '';\n  if (!file) {\n    return;\n  }\n\n  if (!(await confirmAction(`确定把“${file.name}”导入到“${selectedSlotTitle()}”吗？这会覆盖选中的存档。`, '导入存档'))) {\n    return;\n  }\n\n  await runAction('导入存档', async () => {\n    const imported = await props.services.save.importSlot(selectedSlotId.value, await file.text());\n    await refreshSlotsQuietly();\n    selectedMode.value = imported.meta.mode === '未选择' ? selectedMode.value : imported.meta.mode;\n    inspection.value = null;\n    showToast('已导入');\n  });\n}\n\nasync function refreshSlotsQuietly() {\n  slots.value = await props.services.save.listSlots();\n}\n\nasync function continueGame() {\n  refreshRuntime();\n  if (!runtime.value.activeSlotId) {\n    showToast('还没有正在游玩的存档');\n    activePanel.value = 'landing';\n    return;\n  }\n  if (!(await confirmAction('确定继续当前存档吗？当前聊天会切换到正在游玩的存档；当前内容若未保存，不会另行保存。', '继续游戏'))) {\n    return;\n  }\n  await loadSlot(runtime.value.activeSlotId);\n}\n\nfunction updateSetting(key: SettingKey, value: string) {\n  settings.value = patchTangquanUiSettings({ [key]: value } as Partial<TangquanUiSettings>);\n  props.services.log.info('设置', '显示设置已更新', { key, value });\n  showToast('设置已保存');\n}\n\nfunction refreshLogs() {\n  logEntries.value = props.services.log.snapshot().slice().reverse();\n}\n\nfunction serializeLogs() {\n  return props.services.log\n    .snapshot()\n    .map(entry => `[${entry.at}] ${entry.level.toUpperCase()} ${entry.scope} ${entry.message}${entry.detail === undefined ? '' : ` ${formatDetail(entry.detail)}`}`)\n    .join('\\n');\n}\n\nasync function copyLogs() {\n  const text = serializeLogs();\n  try {\n    await navigator.clipboard.writeText(text);\n  } catch {\n    const textarea = document.createElement('textarea');\n    textarea.value = text;\n    document.body.appendChild(textarea);\n    textarea.select();\n    document.execCommand('copy');\n    textarea.remove();\n  }\n  showToast('日志已复制');\n}\n\nfunction clearLogs() {\n  props.services.log.clear();\n  props.services.log.info('日志', '日志已清空');\n  refreshLogs();\n  showToast('日志已清空');\n}\n\nfunction formatDate(value: string) {\n  const date = new Date(value);\n  if (Number.isNaN(date.getTime())) {\n    return value || '未知时间';\n  }\n  return date.toLocaleString();\n}\n\nfunction formatMB(value: number) {\n  if (!Number.isFinite(value) || value <= 0) {\n    return '0 MB';\n  }\n  return `${(value / 1024 / 1024).toFixed(2)} MB`;\n}\n\nfunction downloadText(filename: string, content: string, mime: string) {\n  const blob = new Blob([content], { type: `${mime};charset=utf-8` });\n  const url = URL.createObjectURL(blob);\n  const anchor = document.createElement('a');\n  anchor.href = url;\n  anchor.download = filename;\n  document.body.appendChild(anchor);\n  anchor.click();\n  anchor.remove();\n  URL.revokeObjectURL(url);\n}\n\nfunction formatDetail(detail: unknown) {\n  if (typeof detail === 'string') {\n    return detail;\n  }\n  try {\n    return JSON.stringify(detail, null, 2);\n  } catch {\n    return String(detail);\n  }\n}\n\nonMounted(() => {\n  props.services.log.info('Vue前端', '主界面已挂载');\n  refreshRuntime();\n  refreshLogs();\n  if (runtime.value.activeSlotId) {\n    currentSlotLabel.value = '当前存档';\n  }\n});\n</script>\n\n<style scoped>\n* {\n  box-sizing: border-box;\n}\n\nbutton {\n  border: 0;\n  color: inherit;\n  font: inherit;\n  cursor: pointer;\n}\n\nbutton:disabled {\n  cursor: wait;\n  opacity: 0.52;\n}\n\n.visually-hidden {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n  white-space: nowrap;\n  clip-path: inset(50%);\n}\n\n.title-screen,\n.play-screen {\n  --ink: #0b0806;\n  --text: #f7ecdc;\n  --muted: rgba(247, 236, 220, 0.66);\n  --dim: rgba(247, 236, 220, 0.42);\n  --line: rgba(247, 236, 220, 0.2);\n  --line-strong: rgba(247, 236, 220, 0.42);\n  --gold: #d7b36d;\n  --tea: #80aa9c;\n 