import type {
  BossArea,
  BossEmployee,
  BossMarketCandidate,
  BossNomination,
  BossPageState,
  BossProject,
  BossRecruitCandidate,
  BossSettlement,
} from './bossEconomy';

export type TangquanMvuBlockId =
  | 'boss.overview'
  | 'boss.area'
  | 'boss.employee'
  | 'boss.guest'
  | 'boss.service'
  | 'boss.candidate'
  | 'boss.settlement';

export type TangquanMvuBlockStore = {
  activeBlockIds: TangquanMvuBlockId[];
  activeContext: BossMvuBlockContext;
  savedBlocks: Partial<Record<TangquanMvuBlockId, Record<string, unknown>>>;
  updatedAt: string;
};

export type BossMvuBlockContext = {
  areaName?: string;
  employeeName?: string;
  candidateName?: string;
  recruit?: boolean;
  settlement?: boolean;
};

const BLOCK_KEYS: Record<TangquanMvuBlockId, string[]> = {
  'boss.overview': ['店铺概况'],
  'boss.area': ['当前区域'],
  'boss.employee': ['当前员工'],
  'boss.guest': ['当前客人'],
  'boss.service': ['当前服务'],
  'boss.candidate': ['当前候选人'],
  'boss.settlement': ['今日结算'],
};

const ALL_BLOCK_KEYS = _.uniq(Object.values(BLOCK_KEYS).flat());

